// MachinaState diagram editor + simulator (runs inside the VS Code webview).
//
// Plain browser JavaScript: no build step and no modules. The webview HTML generated by
// MachinaEditorProvider.getHtml (src/editorProvider.ts) loads media/machina.js first, which exposes the
// compiled src/model.ts and src/engine.ts as `window.Machina` (bundled by scripts/bundle-webview.js), and
// then this file. Everything lives in one IIFE so nothing leaks into the page's global scope.
//
// STATE
// The document is held as a plain object, `diagram` (the JSON format of the Diagram interface in
// src/model.ts, passed through normalize()). Everything else is view state that never reaches the document:
// the selection (`selection` + `multi`), the active tool (`mode`), the pan/zoom transform (`view`), the
// gesture in progress (`drag`), the simulator session (`sim`), the problems of the last validation
// (`issues`), the grid-snap toggle (`snap`, persisted with vscode.setState) and an internal clipboard.
//
// RENDERING (SVG)
// render() rebuilds the whole SVG scene from `diagram` after every change, including every mousemove of a
// drag; there is no diffing, diagrams are small enough for this to be cheap. All shapes go into the #viewport
// group, whose transform applies `view` (translate, then scale), so the model is stored and drawn in unscaled
// "diagram coordinates" and toDiagram() maps mouse positions back. Pan and zoom only change that transform
// and the dot grid pattern below the viewport, which follows it (applyView()). Draw order is the z-order:
// states sorted by nesting depth (parents below children), then transitions above all states, then the
// feedback of the current gesture. Every clickable element carries data-kind ('state' | 'transition' |
// 'handle') and data-id attributes, and hit testing is simply `event.target.closest('[data-kind]')`, so the
// browser does the geometry. renderPanel() rebuilds the side panel (properties of the selection, group tools,
// or the simulator) and renderIssues() the problem list. All colours come from VS Code theme CSS variables
// in media/editor.css; user colours are set as the `--c` custom property.
//
// INTERACTION MODES
// `mode` is 'select' or a placing tool ('state', 'region', 'initial', 'final', 'history', 'choice',
// 'transition'). In select mode a mousedown starts a drag gesture: pan (empty canvas, middle button, or
// anything while simulating), marquee (Shift+drag on empty canvas), move (a state), resize (the corner handle
// of the selected state) or bend (a transition). A placing tool creates the element where the canvas is
// clicked (nested into the state or region under it) and switches back to select mode; the transition tool
// draws a rubber-band link from the source state to the state under the pointer on mouseup. Keyboard
// shortcuts and native clipboard events cover delete, nudge, select-all, copy/cut/paste and duplicate.
//
// UNDO/REDO AND DOCUMENT SYNC
// The editor keeps no history of its own. Each completed edit calls commit(), which serializes `diagram` and
// posts the full text to the extension host; the host replaces the document text with one WorkspaceEdit, so
// Ctrl+Z / Ctrl+Y are VS Code's ordinary text-document undo and redo. Gestures mutate `diagram` live while
// dragging and commit once on mouseup, so a whole drag is one undo step. The host echoes every document
// change back as an 'update'; `lastText` remembers the text last sent or received so the echo of our own edit
// is ignored, and only real external changes (undo/redo, edits in the text editor, Layout, a file change on
// disk) replace the model.
//
// MESSAGE PROTOCOL (vscode.postMessage / window 'message' events, handled in MachinaEditorProvider)
//   Webview -> host:
//     ready       {}                   once at start-up; the host answers with update + validation
//     edit        { text }             the complete new document text (commit())
//     autoLayout  {}                   arrange the document with the automatic layout (Layout button)
//     generate    { language, style }  generate code for the document (Generate Code button)
//     exportPng   { name, data }       PNG as a data:image/png;base64 URL; the host asks where to save it
//     exportSvg   { name, data }       standalone SVG text starting with '<?xml'
//     openManual  {}                   open the user manual (help dialog)
//     getStarted  {}                   open the Get Started walkthrough (help dialog)
//   Host -> webview:
//     update      { text }             the current document text (on ready and on every change)
//     validation  { issues }           analyze() problems for that text: [{ message, id?, element?, severity? }]
//   Incoming messages without the expected payload are ignored (see the 'message' listener).
//
// SIMULATOR
// "Simulate" switches to a read-only mode that runs the diagram with the shared reference engine:
// Machina.analyze() turns a copy of the diagram into a Machine and Machina.Engine interprets it with exactly
// the semantics of the generated code. The engine reports back through hooks: guard results come from
// user-set checkboxes (`simGuards`, default true), actions and trace events are appended to the trace log,
// timers are only recorded (`sim.timers`) and offered as "after ..." buttons, so simulated time never passes
// by itself, and `fired` highlights the transitions taken by the last step and counts them for coverage.
// Event sequences can be recorded into `diagram.scenarios` and replayed in one go or step by step, with the
// guard results recorded for each step.
//
// test/ui.test.js and docs/tools/harness.html load this file into an ordinary page with a stub
// acquireVsCodeApi() that records the posted messages, and drive it by posting 'update' / 'validation'
// messages exactly as the host does.
(function () {
    'use strict';

    // Webview API handle (acquireVsCodeApi() may only be called once per webview). The elements below are
    // created by the HTML in MachinaEditorProvider.getHtml; the toolbar controls are wired up near the end of
    // this file.
    const vscode = acquireVsCodeApi();
    const SVGNS = 'http://www.w3.org/2000/svg';
    const svg = document.getElementById('canvas');
    const viewport = document.getElementById('viewport');
    const panel = document.getElementById('panel');
    const issuesBox = document.getElementById('issues');
    const parseErrorBox = document.getElementById('parse-error');
    const langSelect = document.getElementById('sel-lang');
    const styleSelect = document.getElementById('sel-style');
    const traceCheck = document.getElementById('chk-trace');
    const threadSafeCheck = document.getElementById('chk-threadsafe');
    const queueCheck = document.getElementById('chk-queue');
    const snapButton = document.getElementById('btn-snap');
    const simButton = document.getElementById('btn-sim');

    // GRID is the snap pitch in diagram units (also the arrow-key nudge step with Snap on). CLIPBOARD_TAG
    // marks clipboard JSON written by this editor, so arbitrary clipboard text is never pasted as diagram
    // content.
    const GRID = 10;
    const CLIPBOARD_TAG = 'machina-state/clipboard';
    // Smallest size of a state or region (resize handle, Same width / height).
    const MIN_WIDTH = 60;
    const MIN_HEIGHT = 40;

    // Editor state (see the file overview).
    // - diagram: the normalized document object, or null while the text is not valid JSON.
    // - lastText: the document text last sent to or received from the host; suppresses the echo of our own
    //   edits.
    // - selection / multi: primary selection and the other selected states (multi is only used with a state
    //   primary).
    // - mode: active tool; view: pan offset (screen pixels) and zoom; fitted: whether the view was fitted
    //   yet.
    // - drag: gesture in progress (see the mouse handlers), null when idle.
    // - sim: simulator session or null; its trailing field list below is out of date, startSim() lists the
    //   actual fields.
    // - issues: problems from the last 'validation' message.
    // - clipboard / pasteCount: internal copy buffer and how often it was pasted (each paste is offset
    //   further).
    let diagram = null;
    let lastText = null;
    let selection = null; // primary selection: { type: 'state' | 'transition', id }
    let multi = new Set(); // additional selected state ids
    let mode = 'select';
    let view = { x: 40, y: 40, scale: 1 };
    let fitted = false;
    let drag = null;
    // Simulator session, or null while editing. Set up by startSim():
    // { machine, issues, engine, log, fired, timers, args, recording, replay, halted }.
    let sim = null;
    let issues = [];
    let snap = (vscode.getState() || {}).snap === true;
    let clipboard = null;
    let pasteCount = 0;

    // ---------------------------------------------------------------- helpers

    /**
     * Creates an HTML element. Attribute keys starting with "on" become event listeners (onclick -> 'click'),
     * "class" sets className and every other key is assigned as a DOM property (value, checked, disabled,
     * title, ...). Children that are null, undefined or false are skipped, so callers can include optional
     * parts inline.
     */
    function el(tag, attrs, ...children) {
        const e = document.createElement(tag);
        for (const [k, v] of Object.entries(attrs || {})) {
            if (k.startsWith('on')) {
                e.addEventListener(k.slice(2), v);
            } else if (k === 'class') {
                e.className = v;
            } else {
                e[k] = v;
            }
        }
        for (const c of children) {
            if (c !== null && c !== undefined && c !== false) {
                e.append(c);
            }
        }
        return e;
    }

    /**
     * Creates an SVG element (in the SVG namespace, which createElement would not use). Attributes are set
     * with setAttribute as strings; `text`, if given, becomes the text content.
     */
    function svgEl(tag, attrs, text) {
        const e = document.createElementNS(SVGNS, tag);
        for (const [k, v] of Object.entries(attrs || {})) {
            e.setAttribute(k, String(v));
        }
        if (text !== undefined) {
            e.textContent = text;
        }
        return e;
    }

    // New ids: base-36 time plus random characters, prefixed with "n" so they never start with a digit;
    // unique enough across sessions and pastes without keeping a counter in the document. The lookups below
    // are linear scans (diagrams are small).
    const newId = () => 'n' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
    const byId = id => diagram.states.find(s => s.id === id);
    const transitionById = id => diagram.transitions.find(t => t.id === id);
    const hasChildren = id => diagram.states.some(s => s.parent === id);

    /**
     * Ids of the ancestors of a state, innermost (the direct parent) first. Stops at a dangling parent id.
     */
    function ancestors(id) {
        const result = [];
        let s = byId(id);
        while (s && s.parent) {
            result.push(s.parent);
            s = byId(s.parent);
        }
        return result;
    }

    // Small predicates:
    // - isInternal: only a self transition with internal: true counts (the flag is ignored when source and
    //   target differ).
    // - isPseudo: kinds that are not real states for naming and event-list purposes (regions included).
    // - isTimeout: an `after(...)` event as typed in the diagram (the simulator's isTimeoutEvent instead
    //   tests the generated event names such as Collecting_After30000ms).
    // - snapValue: rounds to the grid when Snap is on, otherwise to whole units, so stored coordinates stay
    //   integers.
    const isDescendant = (id, ancestorId) => ancestors(id).includes(ancestorId);
    const isInternal = t => t.internal === true && t.source === t.target;
    const isPseudo = s => s.kind === 'initial' || s.kind === 'history' || s.kind === 'choice' || s.kind === 'region';
    const isTimeout = ev => /^after\s*\(/i.test(ev || '');
    const snapValue = v => (snap ? Math.round(v / GRID) * GRID : Math.round(v));

    /**
     * Ids of all selected states (primary first). The primary selection can be a state or a transition;
     * `multi` holds the additional states of a multi-selection, and those whose state no longer exists are
     * skipped.
     */
    function selectedStates() {
        const ids = selection && selection.type === 'state' ? [selection.id] : [];
        for (const id of multi) {
            if (!ids.includes(id) && byId(id)) {
                ids.push(id);
            }
        }
        return ids;
    }

    const isSelectedState = id => selectedStates().includes(id);

    /**
     * Display name of a transition target in the side panel: "choice" for a choice point, "Parent (H)" /
     * "Parent (H*)" for a history pseudostate (named after its composite state), otherwise the state name.
     */
    function targetName(t) {
        const d = byId(t.target);
        if (!d) {
            return '?';
        }
        if (d.kind === 'choice') {
            return 'choice';
        }
        return d.kind === 'history' ? `${d.parent ? byId(d.parent).name : '?'} (${d.deep ? 'H*' : 'H'})` : d.name;
    }

    /**
     * Distinct user event names in use, in order of first use: events of transitions that leave real states,
     * without empty (completion) events and `after(...)` timeouts. These are the events whose parameter lists
     * can be edited in the state machine panel.
     */
    function usedEvents() {
        const names = [];
        for (const t of diagram.transitions) {
            const src = byId(t.source);
            const ev = (t.event || '').trim();
            if (src && !isPseudo(src) && ev && !isTimeout(ev) && !names.includes(ev)) {
                names.push(ev);
            }
        }
        return names;
    }
    // Nesting depth (0 = top level), centre point, and point-in-box test (edges inclusive) on state boxes.
    // Coordinates of nested states are absolute, not relative to the parent.
    const depth = s => ancestors(s.id).length;
    const center = s => ({ x: s.x + s.w / 2, y: s.y + s.h / 2 });
    const contains = (outer, p) => p.x >= outer.x && p.x <= outer.x + outer.w && p.y >= outer.y && p.y <= outer.y + outer.h;

    /** First of `base1`, `base2`, ... that no state uses as its name. */
    function uniqueName(base) {
        const names = new Set(diagram.states.map(s => s.name));
        let i = 1;
        while (names.has(base + i)) {
            i++;
        }
        return base + i;
    }

    /**
     * Coerces parsed document JSON into the shape the editor relies on (mirrors parseDiagram in
     * src/model.ts): missing or wrongly typed members get defaults, and the codegen options are completed
     * with the defaults the toolbar shows (C++, switch-based, all options off; a codegen value that is not an
     * object is replaced by them). The known members come first in this order; any other top-level member
     * of the file (e.g. one written by a newer version or another tool) follows unchanged, so a commit never
     * drops it. `scenarios: undefined` disappears when serialized. States, transitions, events and scenarios
     * are kept as the parsed objects and edited in place, so unknown members inside them survive as well.
     */
    function normalize(raw) {
        const d = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
        const codegen = d.codegen && typeof d.codegen === 'object' && !Array.isArray(d.codegen) ? d.codegen : {};
        const result = {
            name: typeof d.name === 'string' ? d.name : 'StateMachine',
            namespace: typeof d.namespace === 'string' ? d.namespace : '',
            states: Array.isArray(d.states) ? d.states : [],
            transitions: Array.isArray(d.transitions) ? d.transitions : [],
            events: d.events && typeof d.events === 'object' && !Array.isArray(d.events) ? d.events : {},
            codegen: Object.assign({ language: 'cpp', style: 'switch', trace: false, threadSafe: false, queue: false }, codegen),
            scenarios: Array.isArray(d.scenarios) ? d.scenarios : undefined
        };
        // Unknown members are carried over after the known ones (`in` also matches the known members whose
        // value is undefined, such as a missing or invalid scenarios list, so those are never copied back).
        for (const [key, value] of Object.entries(d)) {
            if (!(key in result)) {
                result[key] = value;
            }
        }
        return result;
    }

    /**
     * Sends the diagram to the extension host as the complete new document text. This is the only way the
     * editor changes the document; the host applies it as one WorkspaceEdit, so every commit is one undo step
     * in VS Code. An unchanged text (e.g. a click that moved nothing) is not sent at all. `lastText` is
     * updated first so the 'update' the host echoes back is recognised as our own and ignored.
     */
    function commit() {
        const text = JSON.stringify(diagram, null, 2);
        if (text === lastText) {
            return;
        }
        lastText = text;
        vscode.postMessage({ type: 'edit', text });
    }

    /**
     * Converts the client coordinates of a mouse event to diagram coordinates: relative to the canvas, then
     * the inverse of the viewport transform (subtract the pan offset, divide by the zoom).
     */
    function toDiagram(e) {
        const r = svg.getBoundingClientRect();
        return { x: (e.clientX - r.left - view.x) / view.scale, y: (e.clientY - r.top - view.y) / view.scale };
    }

    // Dot grid behind the diagram: a <pattern> with one dot per tile in <defs>, painted by a rect that fills
    // the canvas and lies below #viewport (styled in editor.css). Both are created here rather than in the
    // host's HTML; the pattern is dropped from exports. applyView() keeps the tile aligned with the view.
    const gridDot = svgEl('circle', { r: 1 });
    const gridPattern = svgEl('pattern', { id: 'grid', patternUnits: 'userSpaceOnUse' });
    gridPattern.appendChild(gridDot);
    svg.querySelector('defs').appendChild(gridPattern);
    svg.insertBefore(svgEl('rect', { id: 'grid-fill', width: '100%', height: '100%', fill: 'url(#grid)' }), viewport);

    // Smallest on-screen distance between grid dots, in pixels. Zoomed out further, the grid shows only every
    // 2nd, 5th or 10th snap position, so it never turns into noise; GRID_STEPS are those multiples of GRID.
    const GRID_MIN_PIXELS = 10;
    const GRID_STEPS = [1, 2, 5, 10];

    /**
     * Applies the pan/zoom to the viewport group and the grid pattern. Panning and zooming call only this
     * (not render()), which keeps them cheap. The grid tile is sized in screen pixels (so the dots keep a
     * radius of 1 pixel at any zoom) to the scaled pitch of the coarsest needed multiple of the snap grid,
     * and offset by the pan minus half a tile, so the dot in the tile's centre lies exactly on diagram
     * coordinates that are multiples of that pitch, i.e. on snap positions.
     */
    function applyView() {
        viewport.setAttribute('transform', `translate(${view.x} ${view.y}) scale(${view.scale})`);
        const steps = GRID_STEPS.find(k => GRID * k * view.scale >= GRID_MIN_PIXELS) || GRID_STEPS[GRID_STEPS.length - 1];
        const pitch = GRID * steps * view.scale;
        gridPattern.setAttribute('x', String(view.x - pitch / 2));
        gridPattern.setAttribute('y', String(view.y - pitch / 2));
        gridPattern.setAttribute('width', String(pitch));
        gridPattern.setAttribute('height', String(pitch));
        gridDot.setAttribute('cx', String(pitch / 2));
        gridDot.setAttribute('cy', String(pitch / 2));
    }

    /**
     * Label of a transition in UML notation `event [guard] / action`. Initial transitions show only the
     * action after a slash (they have no trigger or guard); choice branches show `[guard]`, with `[else]` for
     * an empty guard, and the action. An empty string means no label is drawn.
     */
    function transitionLabel(t) {
        const src = byId(t.source);
        const action = (t.action || '').trim();
        if (src && src.kind === 'initial') {
            return action ? '/ ' + action : '';
        }
        if (src && src.kind === 'choice') {
            const guard = (t.guard || '').trim();
            return `[${guard || 'else'}]${action ? ` / ${action}` : ''}`;
        }
        let label = (t.event || '').trim();
        if ((t.guard || '').trim()) {
            label += ` [${t.guard.trim()}]`;
        }
        if (action) {
            label += ` / ${action}`;
        }
        return label;
    }

    // --------------------------------------------------------------- geometry

    /**
     * Point where the ray from the centre of `s` towards `toward` leaves the outline of `s`. Real states are
     * treated as rectangles (the rounded corners are ignored); every other kind (initial, final, history,
     * choice) as a circle of radius w/2, which is close enough for the diamond of a choice point too. Returns
     * the centre if both points coincide.
     */
    function boundaryPoint(s, toward) {
        const c = center(s);
        const dx = toward.x - c.x;
        const dy = toward.y - c.y;
        if (dx === 0 && dy === 0) {
            return c;
        }
        if (s.kind !== 'state') {
            const len = Math.hypot(dx, dy);
            const r = s.w / 2;
            return { x: c.x + (dx / len) * r, y: c.y + (dy / len) * r };
        }
        // Scale the direction so it just reaches the nearer of the vertical and horizontal edges of the box.
        const t = Math.min(dx !== 0 ? s.w / 2 / Math.abs(dx) : Infinity, dy !== 0 ? s.h / 2 / Math.abs(dy) : Infinity);
        return { x: c.x + dx * t, y: c.y + dy * t };
    }

    /**
     * Straight-line frame of a transition between two different states: `p1` / `p2` are the outline points
     * facing each other, `mid` their midpoint and `n` the unit normal of p1 -> p2 (pointing up when the
     * outlines touch). A transition's `bend` is the offset of its control point along `n`; because `n` turns
     * with the direction, the same bend curves A -> B and B -> A to opposite sides.
     * Bends are measured from the straight segment between the two outlines, not the centres, so large
     * (composite) states do not push the control point inside a shape.
     */
    function frame(t) {
        const s = byId(t.source);
        const d = byId(t.target);
        const p1 = boundaryPoint(s, center(d));
        const p2 = boundaryPoint(d, center(s));
        const mid = { x: (p1.x + p2.x) / 2, y: (p1.y + p2.y) / 2 };
        const len = Math.hypot(p2.x - p1.x, p2.y - p1.y);
        const n = len > 0 ? { x: -(p2.y - p1.y) / len, y: (p2.x - p1.x) / len } : { x: 0, y: -1 };
        return { p1, p2, mid, n };
    }

    /**
     * SVG path and label position of a drawn (non-internal) transition: { path, label: { x, y }, anchor }.
     * A self transition is a cubic loop from the top edge, near the top-right corner, out to the right edge;
     * each further self loop of the same state is 16 units larger so the loops nest instead of overlapping
     * (internal transitions are not counted, they are listed inside the state). Any other transition is a
     * quadratic Bezier whose control point lies `bend` units along the normal from the middle of the
     * outline-to-outline segment; when bent, the end points are recomputed towards the control point so the
     * curve leaves and enters the shapes facing it. The label sits just above the curve's midpoint (the
     * quadratic at t = 0.5 is p1/4 + ctrl/2 + p2/4).
     */
    function transitionGeometry(t) {
        const s = byId(t.source);
        const d = byId(t.target);
        if (s === d) {
            const loops = diagram.transitions.filter(x => x.source === s.id && x.target === s.id && !isInternal(x));
            const off = loops.indexOf(t) * 16;
            const sx = s.x + s.w - 24 - off;
            const sy = s.y;
            const ex = s.x + s.w;
            const ey = s.y + 24 + off;
            return {
                path: `M ${sx} ${sy} C ${sx} ${sy - 40 - off}, ${ex + 40 + off} ${ey}, ${ex} ${ey}`,
                label: { x: ex + 12 + off, y: sy - 18 - off },
                anchor: 'start'
            };
        }
        const f = frame(t);
        const bend = t.bend || 0;
        const ctrl = { x: f.mid.x + f.n.x * bend, y: f.mid.y + f.n.y * bend };
        const p1 = bend ? boundaryPoint(s, ctrl) : f.p1;
        const p2 = bend ? boundaryPoint(d, ctrl) : f.p2;
        const lx = 0.25 * p1.x + 0.5 * ctrl.x + 0.25 * p2.x;
        const ly = 0.25 * p1.y + 0.5 * ctrl.y + 0.25 * p2.y;
        return { path: `M ${p1.x} ${p1.y} Q ${ctrl.x} ${ctrl.y} ${p2.x} ${p2.y}`, label: { x: lx, y: ly - 6 }, anchor: 'middle' };
    }

    // -------------------------------------------------------------- rendering

    /**
     * Rebuilds the whole SVG scene from `diagram` (there is no incremental update). The order of appending is
     * the z-order: states sorted by nesting depth so composite states lie below their children (the sort is
     * stable, so equal depths keep document order), then all drawable transitions above the states (internal
     * transitions are text inside their state, and transitions with a missing end are skipped), then the
     * gesture feedback: the rubber-band line of the Transition tool and the marquee. While simulating, the
     * engine's active states are highlighted.
     */
    function render() {
        applyView();
        viewport.textContent = '';
        if (!diagram) {
            return;
        }
        const active = sim && sim.engine ? new Set(sim.engine.activeStates().map(s => s.id)) : new Set();
        const sorted = [...diagram.states].sort((a, b) => depth(a) - depth(b));
        for (const s of sorted) {
            viewport.appendChild(drawState(s, active.has(s.id)));
        }
        for (const t of diagram.transitions) {
            if (byId(t.source) && byId(t.target) && !isInternal(t)) {
                viewport.appendChild(drawTransition(t));
            }
        }
        if (drag && drag.type === 'link') {
            const c = center(byId(drag.from));
            viewport.appendChild(svgEl('line', { class: 'rubber', x1: c.x, y1: c.y, x2: drag.p.x, y2: drag.p.y }));
        }
        if (drag && drag.type === 'marquee') {
            const r = rectOf(drag.start, drag.p);
            viewport.appendChild(svgEl('rect', { class: 'marquee', x: r.x, y: r.y, width: r.w, height: r.h }));
        }
    }

    // Normalised rectangle spanned by two opposite corners (the marquee).
    const rectOf = (a, b) => ({ x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(a.x - b.x), h: Math.abs(a.y - b.y) });

    /**
     * Draws one state as an SVG group carrying data-kind="state" (the hit-test target) and classes for its
     * kind, selection and simulator activity. Pseudostates are simple shapes: initial = filled dot, history =
     * circle with H / H*, choice = diamond, final = bull's-eye with the name below it. A region is a dashed
     * box with an italic title. A real state is a rounded box with its name (top-left when composite, so its
     * children have room; centred otherwise), a separator line and a compartment listing its entry / exit
     * actions and internal transitions, the latter clickable on their own (data-kind="transition"). A single
     * selected state or region gets a resize handle at its bottom-right corner (not while simulating).
     */
    function drawState(s, isActive) {
        const selected = isSelectedState(s.id);
        const g = svgEl('g', {
            class: `node ${s.kind}${selected ? ' selected' : ''}${isActive ? ' active' : ''}`,
            'data-kind': 'state',
            'data-id': s.id
        });
        applyColor(g, s.color);
        const c = center(s);
        if (s.kind === 'initial') {
            g.appendChild(svgEl('circle', { class: 'shape', cx: c.x, cy: c.y, r: s.w / 2 - 3 }));
            return g;
        }
        if (s.kind === 'history') {
            g.appendChild(svgEl('circle', { class: 'shape', cx: c.x, cy: c.y, r: s.w / 2 }));
            g.appendChild(svgEl('text', { class: 'htext', x: c.x, y: c.y + 4.5, 'text-anchor': 'middle' }, s.deep ? 'H*' : 'H'));
            return g;
        }
        if (s.kind === 'choice') {
            const r = s.w / 2;
            g.appendChild(svgEl('polygon', { class: 'shape', points: `${c.x},${c.y - r} ${c.x + r},${c.y} ${c.x},${c.y + r} ${c.x - r},${c.y}` }));
            return g;
        }
        if (s.kind === 'final') {
            g.appendChild(svgEl('circle', { class: 'shape', cx: c.x, cy: c.y, r: s.w / 2 }));
            g.appendChild(svgEl('circle', { class: 'dot', cx: c.x, cy: c.y, r: s.w / 2 - 5 }));
            g.appendChild(svgEl('text', { class: 'small', x: c.x, y: s.y + s.h + 14, 'text-anchor': 'middle' }, s.name));
            return g;
        }
        if (s.kind === 'region') {
            g.appendChild(svgEl('rect', { class: 'shape', x: s.x, y: s.y, width: s.w, height: s.h }));
            g.appendChild(svgEl('text', { class: 'small region-title', x: s.x + 6, y: s.y + 13 }, s.name));
            // The handle lives inside the state's group but has its own data-kind, so closest() finds the
            // handle, not the state, when it is grabbed.
            if (selected && !sim && selectedStates().length === 1) {
                g.appendChild(svgEl('rect', { class: 'handle', 'data-kind': 'handle', 'data-id': s.id, x: s.x + s.w - 6, y: s.y + s.h - 6, width: 10, height: 10 }));
            }
            return g;
        }
        g.appendChild(svgEl('rect', { class: 'shape', x: s.x, y: s.y, width: s.w, height: s.h, rx: 10, ry: 10 }));
        const composite = hasChildren(s.id);
        const lines = [];
        if ((s.entry || '').trim()) {
            lines.push({ text: 'entry / ' + s.entry.trim() });
        }
        if ((s.exit || '').trim()) {
            lines.push({ text: 'exit / ' + s.exit.trim() });
        }
        for (const t of diagram.transitions) {
            if (t.source === s.id && isInternal(t)) {
                lines.push({ text: transitionLabel(t) || '(internal)', transition: t });
            }
        }
        g.appendChild(
            svgEl(
                'text',
                composite
                    ? { class: 'title', x: s.x + 10, y: s.y + 19, 'text-anchor': 'start' }
                    : { class: 'title', x: c.x, y: s.y + 19, 'text-anchor': 'middle' },
                s.name
            )
        );
        // The separator is drawn for composite states and whenever the compartment has lines; compartment
        // lines are 15 units apart.
        if (composite || lines.length) {
            g.appendChild(svgEl('line', { class: 'sep', x1: s.x, y1: s.y + 27, x2: s.x + s.w, y2: s.y + 27 }));
        }
        lines.forEach((line, i) => {
            const attrs = { class: 'small', x: s.x + 8, y: s.y + 43 + i * 15 };
            // Internal transition lines are styled like edges: selected, fired in the last simulator step, or
            // untaken in coverage mode, and with their own colour.
            if (line.transition) {
                const t = line.transition;
                const selectedT = selection && selection.type === 'transition' && selection.id === t.id;
                const firedT = sim && sim.fired.has(t.id);
                const untaken = sim && showCoverage && !coverage.has(t.id);
                attrs.class = `small internal${selectedT ? ' selected' : ''}${firedT ? ' fired' : ''}${untaken ? ' uncovered' : ''}`;
                attrs['data-kind'] = 'transition';
                attrs['data-id'] = t.id;
            }
            const text = svgEl('text', attrs, line.text);
            if (line.transition) {
                applyColor(text, line.transition.color);
            }
            g.appendChild(text);
        });
        if (selected && !sim && selectedStates().length === 1) {
            g.appendChild(svgEl('rect', { class: 'handle', 'data-kind': 'handle', 'data-id': s.id, x: s.x + s.w - 6, y: s.y + s.h - 6, width: 10, height: 10 }));
        }
        return g;
    }

    /**
     * Draws a transition as an SVG group with data-kind="transition": a wide invisible `hit` path that makes
     * the thin line easy to click, the visible line with an arrowhead, and the label. Classes mark the
     * selection, transitions fired by the last simulator step and, with "Highlight untaken", coverable
     * transitions never taken. The arrowhead follows the same precedence as the line colour in editor.css
     * (fired, then selected, then untaken, then the user colour, then the theme default); see arrowMarker.
     */
    function drawTransition(t) {
        const selected = selection && selection.type === 'transition' && selection.id === t.id;
        const fired = sim && sim.fired.has(t.id);
        const untaken = sim && showCoverage && coverable(t) && !coverage.has(t.id);
        const g = svgEl('g', { class: `edge${selected ? ' selected' : ''}${fired ? ' fired' : ''}${untaken ? ' uncovered' : ''}`, 'data-kind': 'transition', 'data-id': t.id });
        const color = applyColor(g, t.color);
        const geo = transitionGeometry(t);
        const marker = fired ? 'fired' : selected ? 'selected' : untaken ? 'uncovered' : color;
        g.appendChild(svgEl('path', { class: 'hit', d: geo.path }));
        g.appendChild(svgEl('path', { class: 'line', d: geo.path, 'marker-end': arrowMarker(marker) }));
        const label = transitionLabel(t);
        if (label) {
            g.appendChild(svgEl('text', { class: 'label', x: geo.label.x, y: geo.label.y, 'text-anchor': geo.anchor }, label));
        }
        return g;
    }

    // Colour presets of the swatch row in the side panel (other colours come from the colour picker). Only
    // `#rrggbb` values are accepted; any other `color` value in the file is ignored and the theme colour
    // used.
    const PALETTE = ['#e06c75', '#e5a50a', '#98c379', '#56b6c2', '#61afef', '#c678dd', '#d19a66', '#9aa5b1'];
    const validColor = c => (typeof c === 'string' && /^#[0-9a-fA-F]{6}$/.test(c) ? c.toLowerCase() : null);

    /**
     * Applies a user colour to an SVG element: adds the `colored` class and sets the `--c` custom property
     * used by the colored rules in editor.css. A missing or invalid colour leaves the theme styling alone.
     * Returns the normalised colour or null.
     */
    function applyColor(g, value) {
        const color = validColor(value);
        if (color) {
            g.classList.add('colored');
            g.style.setProperty('--c', color);
        }
        return color;
    }

    /**
     * Arrowheads cannot inherit the line colour (a marker is rendered from <defs>, outside the edge group, so
     * neither the edge's classes nor its --c reach it; `context-stroke` would, but the Chromium of older
     * VS Code versions and many SVG viewers of the exported files do not support it). So every look of an
     * edge gets its own marker, cloned once from the default #arrow marker in <defs> and reused afterwards:
     * - 'fired', 'selected', 'uncovered': #arrow-fired / #arrow-selected / #arrow-uncovered, whose fill comes
     *   from the matching theme rule in editor.css (so they follow theme changes);
     * - a user colour '#rrggbb': #arrow-rrggbb with the colour as an inline fill;
     * - null: the default #arrow.
     * Returns the value for the marker-end attribute.
     */
    function arrowMarker(look) {
        if (!look) {
            return 'url(#arrow)';
        }
        const id = 'arrow-' + look.replace(/^#/, '');
        if (!document.getElementById(id)) {
            const marker = document.getElementById('arrow').cloneNode(true);
            marker.id = id;
            if (look.startsWith('#')) {
                marker.querySelector('path').style.fill = look;
            }
            svg.querySelector('defs').appendChild(marker);
        }
        return `url(#${id})`;
    }

    // ------------------------------------------------------------ side panel

    /**
     * Colour field of the side panel for a state or transition: the palette swatches, a native colour picker
     * (applied on 'change', i.e. when a colour is picked, not while dragging in the picker) and a Default
     * button that removes the `color` member. Each change commits and redraws canvas and panel.
     */
    function colorField(obj) {
        const current = validColor(obj.color);
        const apply = c => {
            if (c) {
                obj.color = c;
            } else {
                delete obj.color;
            }
            commit();
            render();
            renderPanel();
        };
        const row = el('div', { class: 'swatches' });
        for (const c of PALETTE) {
            const b = el('button', { class: 'swatch' + (c === current ? ' on' : ''), title: c, onclick: () => apply(c) });
            b.style.setProperty('--c', c);
            row.append(b);
        }
        const picker = el('input', { type: 'color', value: current || '#61afef', title: 'Custom color' });
        picker.addEventListener('change', () => apply(validColor(picker.value)));
        row.append(picker, el('button', { title: 'Use the theme default color', disabled: !current, onclick: () => apply(null) }, 'Default'));
        return el('div', { class: 'field' }, el('span', {}, 'Color'), row);
    }

    /**
     * Labelled text input bound to a model value. `onCommit` receives the trimmed text on 'change' (blur, or
     * Enter, which blurs the input); then the edit is committed and the canvas redrawn, but the panel is not
     * rebuilt. options: placeholder, disabled, and id ('prop-name' is the name field that a double-click on a
     * state focuses).
     */
    function field(label, value, onCommit, options) {
        const opts = options || {};
        const input = el('input', { type: 'text', value: value || '', placeholder: opts.placeholder || '', disabled: !!opts.disabled });
        if (opts.id) {
            input.id = opts.id;
        }
        input.addEventListener('change', () => {
            onCommit(input.value.trim());
            commit();
            render();
        });
        input.addEventListener('keydown', e => {
            if (e.key === 'Enter') {
                input.blur();
            }
        });
        return el('label', { class: 'field' }, el('span', {}, label), input);
    }

    /**
     * Labelled checkbox bound to a model flag. A change commits and rebuilds both canvas and panel, because
     * the flag can change the panel itself (e.g. the title of an internal transition).
     */
    function checkbox(label, checked, onCommit, title) {
        const input = el('input', { type: 'checkbox', checked: !!checked });
        input.addEventListener('change', () => {
            onCommit(input.checked);
            commit();
            render();
            renderPanel();
        });
        return el('label', { class: 'check field-check', title: title || '' }, input, label);
    }

    /**
     * Rebuilds the side panel for the current context: the simulator panel while simulating; group tools for
     * a multi-selection; the state machine properties (class name, namespace, event parameter lists) and help
     * text when nothing is selected; otherwise the properties of the selected state, pseudostate, region or
     * transition. The fields edit the model objects in place and commit on change.
     */
    function renderPanel() {
        panel.textContent = '';
        if (!diagram) {
            return;
        }
        if (sim) {
            renderSimPanel();
            return;
        }
        const group = selectedStates();
        if (group.length > 1) {
            renderGroupPanel(group);
            return;
        }
        const sel = selection && (selection.type === 'state' ? byId(selection.id) : transitionById(selection.id));
        if (!sel) {
            const events = usedEvents();
            panel.append(
                el('h3', {}, 'State machine'),
                field('Class name', diagram.name, v => (diagram.name = v)),
                field('Namespace', diagram.namespace, v => (diagram.namespace = v), { placeholder: 'optional, e.g. App.Control' })
            );
            // Parameter lists are stored per event name in diagram.events; clearing a field removes the
            // entry.
            if (events.length) {
                panel.append(
                    el('h4', {}, 'Event parameters'),
                    el('p', { class: 'muted' }, 'Passed to the guards and actions of transitions triggered by the event. Use types of the target language.')
                );
                for (const ev of events) {
                    panel.append(
                        field(ev, diagram.events[ev], v => {
                            if (v) {
                                diagram.events[ev] = v;
                            } else {
                                delete diagram.events[ev];
                            }
                        }, { placeholder: 'none, e.g. int level, const std::string& name' })
                    );
                }
            }
            panel.append(
                el(
                    'div',
                    { class: 'help' },
                    el('p', {}, 'Pick a tool, then click the canvas to add elements. Drop a state inside another state to nest it; every region needs an initial pseudostate.'),
                    el('p', {}, 'Drag with the Transition tool from source to target. Drag a transition label to bend it. Self transitions can be made internal.'),
                    el('p', {}, 'Events: a name ("Start"), a timeout ("after(500ms)", "after(2s)") or empty for a completion transition, which fires when the state is entered or its region reaches a final state.'),
                    el('p', {}, 'A choice point (diamond) branches on guards; give one branch the guard "else". A history pseudostate (H / H*) resumes the last active substate.'),
                    el('p', {}, 'Guards and actions are method names (e.g. "isReady", "!isBusy", "open; log"). The generated class declares them as abstract hooks.'),
                    el('p', {}, 'Shift+click or Shift+drag selects several states. Ctrl+C / Ctrl+V / Ctrl+X copy, paste and cut; Ctrl+D duplicates; arrow keys nudge.'),
                    el('p', {}, 'Pan: drag empty canvas or middle mouse. Zoom: mouse wheel.')
                )
            );
            return;
        }
        if (selection.type === 'state') {
            const s = sel;
            const parentName = s.parent ? byId(s.parent).name : '(top level)';
            if (s.kind === 'initial') {
                panel.append(el('h3', {}, 'Initial pseudostate'), el('p', { class: 'muted' }, `Region: ${parentName}`));
            } else if (s.kind === 'choice') {
                panel.append(
                    el('h3', {}, 'Choice point'),
                    el('p', { class: 'muted' }, `Region: ${parentName}`),
                    el('p', { class: 'muted' }, 'Outgoing branches carry a guard (or "else") and an optional action. Guards are evaluated before the transition starts; the first true branch is taken, "else" last.')
                );
            } else if (s.kind === 'history') {
                panel.append(
                    el('h3', {}, 'History pseudostate'),
                    el('p', { class: 'muted' }, `Composite state: ${parentName}`),
                    checkbox('Deep history (H*)', s.deep, v => (s.deep = v), 'Shallow history resumes the last direct substate; deep history resumes the innermost state.'),
                    el('p', { class: 'muted' }, 'Without recorded history, the composite state is entered through its initial pseudostate.')
                );
            } else if (s.kind === 'region') {
                panel.append(
                    el('h3', {}, 'Region'),
                    field('Name', s.name, v => (s.name = v), { id: 'prop-name' }),
                    el('p', { class: 'muted' }, `Orthogonal state: ${parentName}`),
                    el(
                        'p',
                        { class: 'muted' },
                        'All regions of a state are active at the same time. Each region needs its own initial pseudostate; transitions between regions are not allowed. The state completes when every region has reached a final state.'
                    )
                );
            } else {
                // The heading names the role of the state: two or more regions make it orthogonal, any
                // children composite.
                const regions = diagram.states.filter(x => x.kind === 'region' && x.parent === s.id).length;
                panel.append(
                    el('h3', {}, s.kind === 'final' ? 'Final state' : regions > 1 ? 'Orthogonal state' : hasChildren(s.id) ? 'Composite state' : 'State'),
                    field('Name', s.name, v => (s.name = v), { id: 'prop-name' }),
                    el('p', { class: 'muted' }, `Parent: ${parentName}`)
                );
                if (s.kind === 'state') {
                    panel.append(
                        field('Entry actions', s.entry, v => (s.entry = v), { placeholder: 'e.g. startTimer; lightOn' }),
                        field('Exit actions', s.exit, v => (s.exit = v), { placeholder: 'e.g. stopTimer' })
                    );
                }
            }
            panel.append(colorField(s));
            return;
        }
        const t = sel;
        if (!byId(t.source) || !byId(t.target)) {
            panel.append(el('p', { class: 'muted' }, 'This transition references a missing state.'));
            return;
        }
        // The editable fields depend on the role of the transition: an initial transition has only an action;
        // a choice branch has a guard (or "else") and an action but no event; only self transitions of real
        // states can be made internal.
        const fromInitial = byId(t.source).kind === 'initial';
        const fromChoice = byId(t.source).kind === 'choice';
        const selfLoop = t.source === t.target && byId(t.source).kind === 'state';
        const completion = !fromInitial && !fromChoice && !(t.event || '').trim();
        const title = fromInitial
            ? 'Initial transition'
            : fromChoice
              ? 'Choice branch'
              : isInternal(t)
                ? 'Internal transition'
                : completion
                  ? 'Completion transition'
                  : isTimeout(t.event)
                    ? 'Timeout transition'
                    : 'Transition';
        panel.append(
            el('h3', {}, title),
            el('p', { class: 'muted' }, isInternal(t) ? `in ${byId(t.source).name}` : `${byId(t.source).name} \u2192 ${targetName(t)}`),
            field('Event', fromInitial || fromChoice ? '' : t.event, v => (t.event = v), {
                disabled: fromInitial || fromChoice,
                placeholder: 'e.g. Start, after(2s), or empty = completion'
            }),
            field('Guard', fromInitial ? '' : t.guard, v => (t.guard = v), {
                disabled: fromInitial,
                placeholder: fromChoice ? 'e.g. hasCredit, or else' : 'e.g. isReady or !isBusy'
            }),
            field('Action', t.action, v => (t.action = v), { placeholder: 'e.g. reset; notify' }),
            selfLoop
                ? checkbox('Internal (no exit / entry)', t.internal, v => {
                      if (v) {
                          t.internal = true;
                      } else {
                          delete t.internal;
                      }
                  }, 'Run the action without leaving and re-entering the state')
                : '',
            colorField(t),
            el(
                'button',
                {
                    onclick: () => {
                        t.bend = 0;
                        commit();
                        render();
                    }
                },
                'Straighten'
            )
        );
    }

    /**
     * Side panel for a multi-selection: align, distribute and same-size tools. The primary (first) selected
     * state is the reference for align, and the first selected real state for size; clicking a selected
     * state makes it the primary.
     */
    function renderGroupPanel(ids) {
        const button = (label, title, fn) => el('button', { title, onclick: fn }, label);
        panel.append(
            el('h3', {}, `${ids.length} states selected`),
            el('h4', {}, 'Align'),
            el(
                'div',
                { class: 'grid-buttons' },
                button('Left', 'Align left edges', () => align(ids, 'left')),
                button('Center', 'Align horizontal centres', () => align(ids, 'center')),
                button('Right', 'Align right edges', () => align(ids, 'right')),
                button('Top', 'Align top edges', () => align(ids, 'top')),
                button('Middle', 'Align vertical centres', () => align(ids, 'middle')),
                button('Bottom', 'Align bottom edges', () => align(ids, 'bottom'))
            ),
            el('h4', {}, 'Distribute'),
            el(
                'div',
                { class: 'grid-buttons' },
                button('Horizontally', 'Equal horizontal gaps', () => distribute(ids, 'x')),
                button('Vertically', 'Equal vertical gaps', () => distribute(ids, 'y'))
            ),
            el('h4', {}, 'Size'),
            el(
                'div',
                { class: 'grid-buttons' },
                button('Same width', 'Give the selected states the width of the first selected state (pseudostates and regions are skipped)', () => sameSize(ids, 'w')),
                button('Same height', 'Give the selected states the height of the first selected state (pseudostates and regions are skipped)', () => sameSize(ids, 'h'))
            ),
            el('p', { class: 'muted' }, 'Ctrl+C / Ctrl+X / Ctrl+V copy, cut and paste; Ctrl+D duplicates; Delete removes the selection.')
        );
    }

    /**
     * Moves a state and everything nested inside it (nested states have absolute coordinates, so they must
     * move explicitly).
     */
    function moveBy(id, dx, dy) {
        for (const s of diagram.states) {
            if (s.id === id || isDescendant(s.id, id)) {
                s.x += dx;
                s.y += dy;
            }
        }
    }

    /** Selected states without those nested in another selected state (they move with their parent). */
    function topLevelOf(ids) {
        return ids.filter(id => !ids.some(other => other !== id && isDescendant(id, other)));
    }

    /**
     * Aligns the selected states with an edge or centre line of the reference state ids[0]. Only top-level
     * members of the selection move (their content follows); deltas are rounded to whole units. One commit,
     * so one undo step.
     */
    function align(ids, how) {
        const states = topLevelOf(ids).map(byId);
        const ref = byId(ids[0]);
        for (const s of states) {
            let dx = 0;
            let dy = 0;
            switch (how) {
                case 'left': dx = ref.x - s.x; break;
                case 'center': dx = ref.x + ref.w / 2 - (s.x + s.w / 2); break;
                case 'right': dx = ref.x + ref.w - (s.x + s.w); break;
                case 'top': dy = ref.y - s.y; break;
                case 'middle': dy = ref.y + ref.h / 2 - (s.y + s.h / 2); break;
                case 'bottom': dy = ref.y + ref.h - (s.y + s.h); break;
            }
            moveBy(s.id, Math.round(dx), Math.round(dy));
        }
        commit();
        render();
    }

    /**
     * Spreads the selected states along an axis with equal gaps, keeping the first and last (by position) in
     * place. Needs at least three top-level states; the gap becomes negative when the states overlap.
     */
    function distribute(ids, axis) {
        const size = axis === 'x' ? 'w' : 'h';
        const states = topLevelOf(ids).map(byId).sort((a, b) => a[axis] - b[axis]);
        if (states.length < 3) {
            return;
        }
        const first = states[0];
        const last = states[states.length - 1];
        const total = states.reduce((sum, s) => sum + s[size], 0);
        const gap = (last[axis] + last[size] - first[axis] - total) / (states.length - 1);
        let pos = first[axis] + first[size] + gap;
        for (const s of states.slice(1, -1)) {
            const delta = Math.round(pos - s[axis]);
            moveBy(s.id, axis === 'x' ? delta : 0, axis === 'y' ? delta : 0);
            pos += s[size] + gap;
        }
        commit();
        render();
    }

    /**
     * Gives the selected real states the width or height of the first selected real state (pseudostates and
     * regions neither serve as the reference nor change size; with fewer than two real states nothing happens). The
     * minimum size of interactive resizing applies. Like the end of a resize, each resized state is then
     * re-nested (renestResized), since it may now cover siblings or no longer contain some of its children.
     */
    function sameSize(ids, size) {
        const states = ids.map(byId).filter(s => s && s.kind === 'state');
        if (states.length < 2) {
            return;
        }
        const value = Math.max(size === 'w' ? MIN_WIDTH : MIN_HEIGHT, states[0][size]);
        for (const s of states) {
            s[size] = value;
        }
        states.forEach(renestResized);
        commit();
        render();
    }

    /**
     * The element a problem refers to, as a selection ({ type, id }), or null when the problem has no id,
     * the id matches no state or transition of the current diagram (e.g. it was deleted, or the analyzer
     * reports the machine as a whole), or there is no diagram (invalid JSON).
     */
    function issueTarget(issue) {
        if (!diagram || typeof issue.id !== 'string') {
            return null;
        }
        // The analyser says which kind of element it means (issue.element) when it knows; a state and a
        // transition may share an id. Without the hint states are tried first.
        const state = byId(issue.id) ? { type: 'state', id: issue.id } : null;
        const transition = transitionById(issue.id) ? { type: 'transition', id: issue.id } : null;
        return issue.element === 'transition' ? transition || state : state || transition;
    }

    /**
     * Renders the problem list from the last 'validation' message. Problems whose id names an element of the
     * diagram are links that make that state or transition the only selection (not while simulating);
     * other problems are plain text. The list is also redrawn on every document update, because the link
     * targets depend on the diagram.
     */
    function renderIssues() {
        issuesBox.textContent = '';
        issuesBox.append(el('h4', {}, issues.length ? `Problems (${issues.length})` : 'No problems'));
        // Warnings (severity 'warning') do not stop simulation or code generation and are drawn in the
        // warning colour; everything else is an error.
        const list = el('ul', {});
        for (const issue of issues) {
            const linked = issueTarget(issue) !== null;
            list.append(
                el(
                    'li',
                    {
                        class: [linked ? 'link' : '', issue.severity === 'warning' ? 'warning' : ''].join(' ').trim(),
                        onclick: () => {
                            // Looked up again: the diagram may have changed since the list was drawn.
                            const target = issueTarget(issue);
                            if (target && !sim) {
                                select(target);
                            }
                        }
                    },
                    issue.message
                )
            );
        }
        issuesBox.append(list);
    }

    // ------------------------------------------------------------- simulation
    // The simulator runs the shared reference engine (media/machina.js, built from src/engine.ts), which
    // implements exactly the semantics of the generated code; the test suite checks both agree.

    // `simGuards` and `coverage` live outside `sim`: guard choices survive Reset and replays, and coverage
    // accumulates over resets until the simulation is stopped or Clear is pressed.
    const outgoing = id => diagram.transitions.filter(t => t.source === id);
    const simGuards = {}; // guard name -> result used by the simulator (default true)
    let coverage = new Map(); // transition / choice branch id -> times taken
    let showCoverage = false;

    /** Transitions that can be taken (and therefore covered); initial transitions are always taken. */
    const coverable = t => {
        const s = byId(t.source);
        return !!s && (s.kind === 'state' || s.kind === 'choice');
    };
    // formatArgs renders hook arguments for the trace (strings quoted). isTimeoutEvent tests a generated
    // event name (e.g. Collecting_After30000ms) against the machine's timers; it is only valid while
    // simulating.
    const formatArgs = args => args.map(a => (typeof a === 'string' ? JSON.stringify(a) : String(a))).join(', ');
    const isTimeoutEvent = event => sim.machine.timers.some(t => t.event === event);

    /**
     * Parses the comma-separated argument text typed next to an event button: numbers and true / false become
     * numbers and booleans, anything else a string (surrounding double quotes removed). Commas inside strings
     * are not supported.
     */
    function parseArgs(text) {
        if (!text.trim()) {
            return [];
        }
        return text.split(',').map(x => {
            const v = x.trim();
            if (/^-?\d+(\.\d+)?$/.test(v)) {
                return Number(v);
            }
            if (v === 'true' || v === 'false') {
                return v === 'true';
            }
            return v.replace(/^"(.*)"$/, '$1');
        });
    }

    /**
     * (Re)starts the simulation from scratch. A deep copy of the diagram is analyzed, so the engine never
     * sees later edits; if there are no blocking problems a Machina.Engine is created with the simulator
     * hooks and started (running the initial transitions). Used by Simulate, Reset, Record and replays, and
     * on every external document update while simulating. The argument texts typed for events carry over from
     * the previous session, and so does an active recording, restarted empty.
     */
    function startSim() {
        const previous = sim;
        let analysis;
        try {
            analysis = Machina.analyze(JSON.parse(JSON.stringify(diagram)));
        } catch (err) {
            analysis = { machine: null, issues: [{ message: String(err.message || err) }] };
        }
        // Session fields:
        // - machine / issues: result of analyze(); engine: the interpreter, or null when the diagram has
        //   problems.
        // - log: trace entries { kind, text }, where kind is the CSS class of the entry in the trace list.
        // - fired: ids of the transitions and choice branches taken by the last step (highlighted).
        // - timers: running timeouts reported by the engine (startTimer adds, cancelTimer and firing in
        //   simStep remove); args: argument text typed per event.
        // - recording: steps being recorded, or null; replay: { scenario, index } of the scenario being
        //   replayed.
        sim = {
            machine: analysis.machine,
            issues: analysis.issues,
            engine: null,
            log: [],
            fired: new Set(),
            timers: new Map(), // timeout event -> { ms, generation }
            args: previous ? previous.args : {}, // event -> argument text
            recording: previous ? previous.recording && [] : null,
            replay: null,
            halted: false // set by runEngine when the engine gave up on an endless completion loop
        };
        // The simulator panel replaces the property panel and canvas clicks only pan, so the selection is
        // dropped.
        selection = null;
        multi = new Set();
        if (!sim.machine) {
            return;
        }
        const log = (kind, text) => sim.log.push({ kind, text });
        // Engine trace kinds -> trace-list CSS classes (transitions reuse the link colour of the 'history'
        // class).
        const kinds = { Start: 'event', Event: 'event', Ignored: 'error', Transition: 'history', Exit: 'exit', Enter: 'enter' };
        // Hooks called by the engine. Guards answer from the "Guard results" checkboxes (true unless
        // unchecked). Timers do not run in real time: startTimer only records the timer together with the
        // generation the engine expects back, and the user lets it elapse with its "after ..." button
        // (simStep -> dispatchTimeout), which also takes it off the list (timers are one-shot); a restarted
        // timer gets a new generation, so stale timeouts are ignored. fired marks a transition for highlighting and counts it for coverage.
        sim.engine = new Machina.Engine(sim.machine, {
            guard(name, args) {
                const result = simGuards[name] !== false;
                log('action', `  [${name}(${formatArgs(args)})] \u2192 ${result}`);
                return result;
            },
            action(name, args) {
                log('action', `  ${name}(${formatArgs(args)})`);
            },
            trace(kind, name) {
                log(kinds[kind], `${kind.toLowerCase()} ${name}`);
            },
            startTimer(event, ms, generation) {
                sim.timers.set(event, { ms, generation });
            },
            cancelTimer(event) {
                sim.timers.delete(event);
            },
            fired(id) {
                sim.fired.add(id);
                coverage.set(id, (coverage.get(id) || 0) + 1);
            }
        });
        runEngine(() => sim.engine.start());
    }

    /**
     * Runs one engine call (start, dispatch or dispatchTimeout). The engine throws a CompletionLoopError when
     * completion transitions keep firing without settling (a guarded cycle that the analyser cannot rule
     * out). The machine is then stuck in the middle of a step, so the error goes to the trace, the session
     * is marked halted and further events are refused until Reset starts a fresh engine. Any other
     * exception is a bug and is re-thrown.
     */
    function runEngine(call) {
        try {
            call();
        } catch (err) {
            if (!err || err.name !== 'CompletionLoopError') {
                throw err;
            }
            sim.log.push({ kind: 'error', text: err.message });
            sim.log.push({ kind: 'error', text: 'simulation halted; press Reset to start again' });
            sim.halted = true;
        }
    }

    /**
     * Dispatches one event, recording it if requested. A recorded step stores arguments only for events with
     * parameters and only the guards switched off (guards not listed replay as true). `fired` is reset first
     * so only this step's transitions are highlighted. Events with parameters are dispatched as typed
     * (Dispatch<Event>(args)), mirroring the generated API.
     * A timeout event goes through DispatchTimeout with the generation of its running timer. Timers are
     * one-shot: the timer is taken out of `sim.timers` before the dispatch, because firing disarms it in the
     * engine too (a transition that re-enters its state starts it again through startTimer). A timeout whose
     * timer is not running (e.g. a replayed step whose state is no longer active) is stale: it is logged as
     * such and not dispatched at all, as the generated code would never see it.
     */
    function simStep(event, args) {
        if (!sim || !sim.engine || sim.halted) {
            return;
        }
        const params = sim.machine.params.get(event) || [];
        if (sim.recording) {
            const step = { event };
            if (params.length) {
                step.args = args;
            }
            const off = sim.machine.guards.filter(g => simGuards[g] === false);
            if (off.length) {
                step.guards = Object.fromEntries(off.map(g => [g, false]));
            }
            sim.recording.push(step);
        }
        sim.fired = new Set();
        if (isTimeoutEvent(event)) {
            const timer = sim.timers.get(event);
            if (timer) {
                sim.timers.delete(event);
                runEngine(() => sim.engine.dispatchTimeout(event, timer.generation));
            } else {
                sim.log.push({ kind: 'error', text: `stale timeout ${event} ignored: its timer is not running` });
            }
        } else {
            runEngine(() => sim.engine.dispatch(event, args, params.length > 0));
        }
        render();
        renderPanel();
    }

    /**
     * Restarts the simulation and replays a scenario, either all steps at once (Run) or one step per click
     * (Step). If a recording is active it continues and records the replayed steps.
     */
    function startReplay(scenario, all) {
        startSim();
        if (!sim.engine) {
            return;
        }
        sim.replay = { scenario, index: 0 };
        sim.log.push({ kind: 'event', text: `replay "${scenario.name}"` });
        if (all) {
            while (replayNext()) {
                // Replays every step.
            }
        }
        render();
        renderPanel();
    }

    /**
     * Replays the next scenario step with the guard results recorded for it. Returns false when done. Every
     * guard of the machine is set from the step (true unless recorded as false), so the "Guard results"
     * checkboxes show the replayed values afterwards.
     */
    function replayNext() {
        const r = sim && sim.replay;
        if (!r || r.index >= r.scenario.steps.length || sim.halted) {
            return false;
        }
        const step = r.scenario.steps[r.index++];
        sim.machine.guards.forEach(g => (simGuards[g] = !(step.guards && step.guards[g] === false)));
        simStep(step.event, Array.isArray(step.args) ? step.args : []);
        return true;
    }

    /**
     * Restarts the simulation and records every event fired from now on. sim.recording is set before
     * startSim() because startSim() carries a non-null recording over (as a fresh empty array).
     */
    function startRecording() {
        sim.recording = [];
        startSim();
        sim.log.push({ kind: 'event', text: 'recording started' });
        render();
        renderPanel();
    }

    /**
     * Ends recording. With `save`, a non-empty recording is stored in the document as a new scenario named
     * "Scenario <n>" (first unused number).
     */
    function stopRecording(save) {
        const steps = sim.recording || [];
        sim.recording = null;
        if (save && steps.length) {
            const scenarios = diagram.scenarios || [];
            const names = new Set(scenarios.map(s => s.name));
            let i = scenarios.length + 1;
            while (names.has(`Scenario ${i}`)) {
                i++;
            }
            diagram.scenarios = [...scenarios, { name: `Scenario ${i}`, steps }];
            commit();
        }
        renderPanel();
    }

    /**
     * Builds the simulator panel: controls (Reset, Record or Save / Discard, Stop), the active leaf states as
     * paths, one button per user event (dimmed when no active state handles it, with an argument input for
     * events with parameters), running timers, guard result checkboxes, saved scenarios, transition coverage
     * and the trace log. Without an engine only the problems and controls are shown.
     */
    function renderSimPanel() {
        panel.append(el('h3', {}, 'Simulation'));
        const controls = el(
            'div',
            { class: 'row' },
            el('button', { title: 'Restart from the initial state', onclick: () => (startSim(), render(), renderPanel()) }, 'Reset'),
            sim.recording
                ? el('button', { class: 'recording', title: 'Stop recording and save the events as a scenario', onclick: () => stopRecording(true) }, `Save (${sim.recording.length})`)
                : el('button', { title: 'Restart and record the events you fire as a replayable scenario', onclick: startRecording, disabled: !sim.engine }, 'Record'),
            sim.recording ? el('button', { title: 'Stop recording without saving', onclick: () => stopRecording(false) }, 'Discard') : '',
            el('button', { onclick: () => toggleSim() }, 'Stop')
        );
        if (!sim.engine) {
            const list = el('ul', { class: 'problems' });
            sim.issues.forEach(i => list.append(el('li', {}, i.message)));
            panel.append(el('p', { class: 'muted' }, 'The diagram has problems; fix them to simulate it.'), list, controls);
            return;
        }
        const engine = sim.engine;
        const active = engine.activeStates();
        // Leaves are active states without an active child; orthogonal regions give one leaf per region,
        // joined by "|".
        const leaves = active.filter(s => !active.some(c => c.parent === s));
        const pathOf = s => {
            const names = [];
            for (let x = s; x; x = x.parent) {
                names.unshift(x.name);
            }
            return names.join(' \u203a ');
        };
        panel.append(
            el('p', {}, el('span', { class: 'muted' }, 'Active: '), el('strong', {}, leaves.length ? leaves.map(pathOf).join('  |  ') : '(none)')),
            engine.isFinished() ? el('p', { class: 'ok' }, 'State machine finished.') : '',
            controls
        );

        const enabled = engine.enabledEvents();
        const events = el('div', { class: 'events' });
        // Completion and timeout events get no event button: completions run automatically, timeouts have
        // their own buttons below. Dimmed ("idle") buttons still dispatch, and the engine reports the event
        // as ignored.
        for (const e of sim.machine.events.filter(x => x !== 'Completion' && !isTimeoutEvent(x))) {
            const params = sim.machine.params.get(e) || [];
            const button = el(
                'button',
                { class: enabled.has(e) ? '' : 'idle', title: enabled.has(e) ? 'Dispatch' : 'No active state handles this event', onclick: () => simStep(e, parseArgs(sim.args[e] || '')) },
                e
            );
            if (params.length) {
                const input = el('input', { type: 'text', class: 'args', value: sim.args[e] || '', placeholder: params.map(p => p.decl).join(', '), title: 'Arguments, comma-separated' });
                input.addEventListener('input', () => (sim.args[e] = input.value));
                events.append(el('div', { class: 'with-args' }, button, input));
            } else {
                events.append(button);
            }
        }
        panel.append(el('h4', {}, 'Events'), events);

        if (sim.timers.size) {
            const timers = el('div', { class: 'events' });
            for (const [event, timer] of sim.timers) {
                const owner = sim.machine.timers.find(t => t.event === event).state.name;
                const label = timer.ms % 1000 === 0 ? `${timer.ms / 1000} s` : `${timer.ms} ms`;
                timers.append(el('button', { title: `Let the timer of ${owner} elapse`, onclick: () => simStep(event, []) }, `after ${label}`, el('span', { class: 'muted' }, ` in ${owner}`)));
            }
            panel.append(el('h4', {}, 'Running timers'), timers);
        }

        if (sim.machine.guards.length) {
            const guards = el('div', { class: 'guards' });
            for (const g of sim.machine.guards) {
                const input = el('input', { type: 'checkbox', checked: simGuards[g] !== false });
                input.addEventListener('change', () => (simGuards[g] = input.checked));
                guards.append(el('label', { class: 'check' }, input, ` ${g}`));
            }
            panel.append(el('h4', {}, 'Guard results'), guards);
        }

        const scenarios = diagram.scenarios || [];
        if (scenarios.length) {
            const list = el('div', { class: 'scenarios' });
            scenarios.forEach((s, i) => {
                const name = el('input', { type: 'text', value: s.name, title: 'Scenario name' });
                name.addEventListener('change', () => {
                    s.name = name.value.trim() || s.name;
                    commit();
                });
                // Identity check: this scenario object is the one being replayed and steps remain, so offer
                // the next step.
                const replaying = sim.replay && sim.replay.scenario === s && sim.replay.index < s.steps.length;
                list.append(
                    el(
                        'div',
                        { class: 'scenario' },
                        name,
                        el('button', { title: 'Restart and replay all steps', onclick: () => startReplay(s, true) }, 'Run'),
                        replaying
                            ? el('button', { title: 'Replay the next step', onclick: () => (replayNext(), render(), renderPanel()) }, `Step ${sim.replay.index + 1}/${s.steps.length}`)
                            : el('button', { title: 'Restart and replay step by step', onclick: () => startReplay(s, false) }, 'Step'),
                        el(
                            'button',
                            {
                                title: 'Delete the scenario',
                                onclick: () => {
                                    diagram.scenarios = scenarios.filter((_, j) => j !== i);
                                    if (!diagram.scenarios.length) {
                                        delete diagram.scenarios;
                                    }
                                    commit();
                                    renderPanel();
                                }
                            },
                            '\u2715'
                        )
                    )
                );
            });
            panel.append(el('h4', {}, 'Scenarios'), list);
        }

        // Coverage counts transitions that leave states (internal ones included) and choice branches; initial
        // transitions always fire and are not counted.
        const universe = diagram.transitions.filter(coverable);
        const covered = universe.filter(t => coverage.has(t.id));
        const highlight = el('input', { type: 'checkbox', checked: showCoverage });
        highlight.addEventListener('change', () => {
            showCoverage = highlight.checked;
            render();
        });
        panel.append(
            el('h4', {}, `Coverage: ${covered.length}/${universe.length} transitions`),
            el(
                'div',
                { class: 'row' },
                el('label', { class: 'check', title: 'Show transitions that have not been taken yet in red' }, highlight, ' Highlight untaken'),
                el('button', { title: 'Forget which transitions were taken', onclick: () => ((coverage = new Map()), render(), renderPanel()) }, 'Clear')
            )
        );

        panel.append(el('h4', {}, 'Trace'));
        const log = el('ol', { class: 'log' });
        for (const entry of sim.log) {
            log.append(el('li', { class: entry.kind }, entry.text));
        }
        panel.append(log);
        // Keep the newest trace entries in view.
        log.scrollTop = log.scrollHeight;
    }

    /**
     * Starts or stops the simulator. Stopping discards the session and the coverage. The body class
     * `simulating` greys out and disables the editing tools of the toolbar (see editor.css).
     */
    function toggleSim() {
        if (sim) {
            sim = null;
            coverage = new Map();
        } else if (diagram) {
            startSim();
        }
        document.body.classList.toggle('simulating', !!sim);
        simButton.textContent = sim ? 'Stop Simulation' : 'Simulate';
        setMode('select');
        render();
        renderPanel();
    }

    // ---------------------------------------------------------------- editing

    /**
     * Switches the active tool: highlights its toolbar button and shows a crosshair cursor for the placing
     * tools.
     */
    function setMode(m) {
        mode = m;
        document.querySelectorAll('#tools button[data-mode]').forEach(b => b.classList.toggle('on', b.dataset.mode === m));
        svg.classList.toggle('placing', m !== 'select');
    }

    /** Makes `sel` ({ type, id } or null) the only selection and redraws canvas and panel. */
    function select(sel) {
        selection = sel;
        multi = new Set();
        render();
        renderPanel();
    }

    /**
     * Shift/Ctrl+click: adds or removes a state from the multi-selection. Removing the primary promotes the
     * next selected state; a primary transition selection is replaced by the state.
     */
    function toggleSelect(id) {
        const ids = selectedStates();
        if (ids.includes(id)) {
            const rest = ids.filter(x => x !== id);
            selection = rest.length ? { type: 'state', id: rest[0] } : null;
            multi = new Set(rest.slice(1));
        } else if (ids.length === 0) {
            selection = { type: 'state', id };
            multi = new Set();
        } else {
            multi.add(id);
        }
        render();
        renderPanel();
    }

    /** Selects the given state ids; the first becomes the primary (the reference for align and size). */
    function selectMany(ids) {
        selection = ids.length ? { type: 'state', id: ids[0] } : null;
        multi = new Set(ids.slice(1));
        render();
        renderPanel();
    }

    /**
     * Re-nests a state after it was created, moved, resized or pasted. Its new parent is the deepest state or
     * region whose box contains the state's centre, excluding the state itself and its own descendants (which
     * would create a cycle). A state or region then adopts the siblings (elements with the same new parent)
     * that now lie completely inside its box, so drawing or dropping a box around existing states nests them.
     * The state's own children keep it as their parent here; after a size change renestResized() also
     * releases the children that no longer lie inside.
     */
    function reparent(s) {
        const c = center(s);
        let best = null;
        for (const o of diagram.states) {
            // Regions can only be placed in states; everything else goes into the innermost state or region.
            const container = s.kind === 'region' ? o.kind === 'state' : o.kind === 'state' || o.kind === 'region';
            if (o === s || !container || isDescendant(o.id, s.id) || !contains(o, c)) {
                continue;
            }
            if (!best || depth(o) > depth(best)) {
                best = o;
            }
        }
        s.parent = best ? best.id : null;
        // Adopt siblings that now lie completely inside this state or region (only a state can adopt a
        // region).
        if (s.kind === 'state' || s.kind === 'region') {
            for (const o of diagram.states) {
                const fits = o.kind === 'region' ? s.kind === 'state' : true;
                if (o !== s && fits && o.parent === s.parent && contains(s, o) && contains(s, { x: o.x + o.w, y: o.y + o.h })) {
                    o.parent = s.id;
                }
            }
        }
    }

    /**
     * Re-nests a state whose size changed (end of a resize gesture, Same width / height): reparent() nests
     * the state by its new centre and lets it adopt the siblings that now lie completely inside it (growing
     * over states), then every direct child whose centre is no longer inside the box (shrinking past it) is
     * re-nested with reparent() too, i.e. with the same rules as dropping it there after a drag. Grandchildren
     * keep their parents and move along with them.
     */
    function renestResized(s) {
        reparent(s);
        for (const child of diagram.states) {
            if (child.parent === s.id && !contains(s, center(child))) {
                reparent(child);
            }
        }
    }

    /**
     * Adds a new element of `kind` centred on diagram point `p`, with the default size of its kind and a
     * unique default name (pseudostates use fixed names), nests it with reparent(), commits and selects it.
     */
    function createState(kind, p) {
        const sizes = { state: { w: 140, h: 70 }, region: { w: 260, h: 110 }, history: { w: 26, h: 26 }, choice: { w: 30, h: 30 } };
        const size = sizes[kind] || { w: 24, h: 24 };
        const names = {
            state: () => uniqueName('State'),
            region: () => uniqueName('Region'),
            final: () => uniqueName('Final'),
            history: () => 'History',
            choice: () => 'Choice',
            initial: () => 'Initial'
        };
        const s = {
            id: newId(),
            name: names[kind](),
            kind,
            parent: null,
            x: snapValue(p.x - size.w / 2),
            y: snapValue(p.y - size.h / 2),
            w: size.w,
            h: size.h
        };
        if (kind === 'state') {
            s.entry = '';
            s.exit = '';
        }
        if (kind === 'history') {
            s.deep = false;
        }
        diagram.states.push(s);
        reparent(s);
        commit();
        select({ type: 'state', id: s.id });
    }

    /**
     * Adds a transition from `from` to `to` where UML allows one: finals, history pseudostates and regions
     * cannot be sources, initial pseudostates and regions cannot be targets, an initial pseudostate has
     * exactly one outgoing transition and no self loop, and a choice point cannot loop to itself. A new
     * transition gets the placeholder event "Event" (none when leaving an initial or choice pseudostate);
     * further transitions between the same two states (either direction) get bends of 36 units per existing
     * one, so they fan out instead of overlapping.
     */
    function createTransition(from, to) {
        const src = byId(from);
        const dst = byId(to);
        if (!src || !dst || src.kind === 'final' || src.kind === 'history' || src.kind === 'region' || dst.kind === 'initial' || dst.kind === 'region') {
            return;
        }
        if (src.kind === 'initial' && (outgoing(from).length > 0 || from === to)) {
            return;
        }
        if (src.kind === 'choice' && from === to) {
            return;
        }
        const between = diagram.transitions.filter(t => (t.source === from && t.target === to) || (t.source === to && t.target === from)).length;
        const event = src.kind === 'initial' || src.kind === 'choice' ? '' : 'Event';
        const t = { id: newId(), source: from, target: to, event, guard: '', action: '', bend: from === to ? 0 : between * 36 };
        diagram.transitions.push(t);
        commit();
        select({ type: 'transition', id: t.id });
    }

    /**
     * Deletes the selected states with everything nested inside them and every transition attached to a
     * deleted state, or else the selected transition. Disabled while simulating.
     */
    function deleteSelection() {
        if (!selection || sim) {
            return;
        }
        if (selection.type === 'state') {
            const roots = selectedStates();
            const doomed = new Set(diagram.states.filter(s => roots.some(r => s.id === r || isDescendant(s.id, r))).map(s => s.id));
            diagram.states = diagram.states.filter(s => !doomed.has(s.id));
            diagram.transitions = diagram.transitions.filter(t => !doomed.has(t.source) && !doomed.has(t.target));
        } else {
            diagram.transitions = diagram.transitions.filter(t => t.id !== selection.id);
        }
        selection = null;
        multi = new Set();
        commit();
        render();
        renderPanel();
    }

    // ------------------------------------------------------------- clipboard

    /**
     * Serializes the selected states (with nested content) and the transitions between them. The result is a
     * deep copy tagged with CLIPBOARD_TAG that also carries the event parameter lists, so a paste into
     * another diagram keeps them. Returns null when no state is selected; resets the paste offset.
     */
    function copySelection() {
        const roots = selectedStates();
        if (roots.length === 0) {
            return null;
        }
        const states = diagram.states.filter(s => roots.some(r => s.id === r || isDescendant(s.id, r)));
        const ids = new Set(states.map(s => s.id));
        const transitions = diagram.transitions.filter(t => ids.has(t.source) && ids.has(t.target));
        clipboard = JSON.parse(JSON.stringify({ tag: CLIPBOARD_TAG, states, transitions, events: diagram.events }));
        pasteCount = 0;
        return clipboard;
    }

    /**
     * Pastes clipboard data as new elements. Every state gets a fresh id and parent links are remapped within
     * the pasted set; states whose parent was not copied become roots and are nested by reparent() where they
     * land. Each successive paste of the same data is offset 30 units further. Real states whose name is
     * taken get a numeric suffix. Transitions are copied with remapped ends, and event parameter lists
     * missing from this diagram are added (existing ones win). The pasted roots become the selection.
     */
    function paste(data) {
        if (!data || data.tag !== CLIPBOARD_TAG || !Array.isArray(data.states) || sim || !diagram) {
            return;
        }
        pasteCount++;
        const offset = 30 * pasteCount;
        const idMap = new Map(data.states.map(s => [s.id, newId()]));
        const names = new Set(diagram.states.map(s => s.name));
        const roots = [];
        for (const original of data.states) {
            const s = JSON.parse(JSON.stringify(original));
            s.id = idMap.get(original.id);
            s.parent = idMap.has(original.parent) ? idMap.get(original.parent) : null;
            s.x += offset;
            s.y += offset;
            if (!isPseudo(s) && names.has(s.name)) {
                // Strip a trailing number before looking for a free one, so a copy of State1 becomes State2,
                // State3, ...
                const base = s.name.replace(/\d+$/, '');
                let i = 2;
                while (names.has(base + i)) {
                    i++;
                }
                s.name = base + i;
            }
            names.add(s.name);
            diagram.states.push(s);
            if (!idMap.has(original.parent)) {
                roots.push(s);
            }
        }
        for (const original of data.transitions || []) {
            diagram.transitions.push({ ...JSON.parse(JSON.stringify(original)), id: newId(), source: idMap.get(original.source), target: idMap.get(original.target) });
        }
        for (const [ev, params] of Object.entries(data.events || {})) {
            if (!(ev in diagram.events)) {
                diagram.events[ev] = params;
            }
        }
        roots.forEach(reparent);
        commit();
        selectMany(roots.map(s => s.id));
    }

    /**
     * True when a keyboard or clipboard event targets a form control, so the editor shortcuts do not
     * interfere with typing in the side panel.
     */
    function isEditingText(target) {
        const tag = target && target.tagName;
        return tag === 'INPUT' || tag === 'SELECT' || tag === 'TEXTAREA';
    }

    // Copy / cut / paste use the native clipboard events rather than keydown, so Ctrl+C / X / V go through
    // the browser's own clipboard handling. The selection is also put on the system clipboard as tagged JSON,
    // so it can be pasted into another diagram editor. Cutting is not possible while simulating; copying is.
    // While the help dialog is open, all three are left to the browser (text in the help can be copied).
    document.addEventListener('copy', e => {
        if (isEditingText(e.target) || helpOpen() || !copySelection()) {
            return;
        }
        e.clipboardData.setData('text/plain', JSON.stringify(clipboard));
        e.preventDefault();
    });
    document.addEventListener('cut', e => {
        if (isEditingText(e.target) || helpOpen() || sim || !copySelection()) {
            return;
        }
        e.clipboardData.setData('text/plain', JSON.stringify(clipboard));
        e.preventDefault();
        deleteSelection();
    });
    document.addEventListener('paste', e => {
        if (isEditingText(e.target) || helpOpen()) {
            return;
        }
        // Prefer the system clipboard when it holds our format (it may come from another editor); different
        // content restarts the paste offset. Anything else falls back to the internal clipboard.
        let data = clipboard;
        try {
            const parsed = JSON.parse(e.clipboardData.getData('text/plain') || 'null');
            if (parsed && parsed.tag === CLIPBOARD_TAG) {
                if (JSON.stringify(parsed) !== JSON.stringify(clipboard)) {
                    pasteCount = 0;
                }
                data = parsed;
                clipboard = parsed;
            }
        } catch {
            // Not our format: fall back to the internal clipboard.
        }
        e.preventDefault();
        paste(data);
    });

    // Presentation properties copied as inline styles into exported SVG (see inlineStyles). paint-order and
    // the stroke properties keep the background halo of transition labels.
    const EXPORT_STYLE_PROPS = [
        'fill', 'fill-opacity', 'stroke', 'stroke-width', 'stroke-opacity', 'stroke-dasharray', 'stroke-linejoin',
        'paint-order', 'opacity', 'font-family', 'font-size', 'font-weight'
    ];

    /**
     * Theme colors come from CSS variables, which do not exist outside the webview, so bake computed styles
     * in: copies the computed value of every EXPORT_STYLE_PROPS property from each node of `source` to the
     * node at the same position in `clone`. This relies on both trees having the same structure, so it runs
     * before anything is removed from the clone.
     */
    function inlineStyles(source, clone) {
        const from = [source, ...source.querySelectorAll('*')];
        const to = [clone, ...clone.querySelectorAll('*')];
        from.forEach((node, i) => {
            const cs = getComputedStyle(node);
            for (const prop of EXPORT_STYLE_PROPS) {
                to[i].style.setProperty(prop, cs.getPropertyValue(prop));
            }
        });
    }

    /**
     * Exports the diagram as PNG: the standalone SVG (with a background) is decoded as an image, drawn at
     * twice its size onto a canvas, and sent to the host as a data URL; the host shows the save dialog.
     */
    async function exportPng() {
        const exported = buildExportSvg(true);
        if (!exported) {
            return;
        }
        const img = new Image();
        img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(exported.xml);
        await img.decode();
        const scale = 2;
        const canvas = document.createElement('canvas');
        canvas.width = Math.ceil(exported.w * scale);
        canvas.height = Math.ceil(exported.h * scale);
        canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
        vscode.postMessage({ type: 'exportPng', name: diagram.name, data: canvas.toDataURL('image/png') });
    }

    /** Exports the diagram as standalone SVG text (transparent background) for the host to save. */
    function exportSvg() {
        const exported = buildExportSvg(false);
        if (exported) {
            vscode.postMessage({ type: 'exportSvg', name: diagram.name, data: '<?xml version="1.0" encoding="UTF-8"?>\n' + exported.xml });
        }
    }

    /**
     * Standalone SVG of the whole diagram with theme colours baked in. The export always shows the plain
     * diagram: the selection and the simulator session are detached during the export (and restored
     * afterwards), so neither selection colours and handles nor simulator highlights (active states, fired
     * and untaken transitions) are exported; the session itself is untouched. The view box is the content's
     * bounding box in diagram coordinates (the pan/zoom transform is removed) plus 20 units of padding; the
     * invisible hit paths and the grid pattern are dropped. Returns { xml, w, h }, or null for an empty
     * diagram.
     */
    function buildExportSvg(withBackground) {
        if (!diagram || diagram.states.length === 0) {
            return null;
        }
        // render() reads the highlights from `sim` (and `showCoverage` only with a session), so rendering
        // with sim = null draws the editing look. Nothing else runs in between: this function is
        // synchronous.
        const saved = { selection, multi, sim };
        selection = null;
        multi = new Set();
        sim = null;
        render();
        const box = viewport.getBBox();
        const pad = 20;
        const x = box.x - pad;
        const y = box.y - pad;
        const w = box.width + 2 * pad;
        const h = box.height + 2 * pad;

        const out = document.createElementNS(SVGNS, 'svg');
        out.setAttribute('xmlns', SVGNS);
        out.setAttribute('width', String(w));
        out.setAttribute('height', String(h));
        out.setAttribute('viewBox', `${x} ${y} ${w} ${h}`);
        const defs = svg.querySelector('defs');
        const defsClone = defs.cloneNode(true);
        const content = viewport.cloneNode(true);
        inlineStyles(defs, defsClone);
        inlineStyles(viewport, content);
        content.removeAttribute('transform');
        content.querySelectorAll('.hit').forEach(n => n.remove());
        defsClone.querySelector('#grid').remove();
        if (withBackground) {
            out.append(svgEl('rect', { x, y, width: w, height: h, fill: getComputedStyle(document.body).backgroundColor }));
        }
        out.append(defsClone, content);
        selection = saved.selection;
        multi = saved.multi;
        sim = saved.sim;
        render();
        return { xml: new XMLSerializer().serializeToString(out), w, h };
    }

    /**
     * Fits the view to the diagram: scales its bounding box to the canvas (zoom limited to 0.2 - 1.5) and
     * centres it. The box is padded more above (50) and to the right (60), where self loops and labels extend
     * beyond the states. Does nothing while the canvas has no size (e.g. a hidden webview).
     */
    function fit() {
        const r = svg.getBoundingClientRect();
        if (!diagram || r.width === 0) {
            return;
        }
        if (diagram.states.length === 0) {
            view = { x: 40, y: 40, scale: 1 };
        } else {
            const minX = Math.min(...diagram.states.map(s => s.x)) - 30;
            const minY = Math.min(...diagram.states.map(s => s.y)) - 50;
            const maxX = Math.max(...diagram.states.map(s => s.x + s.w)) + 60;
            const maxY = Math.max(...diagram.states.map(s => s.y + s.h)) + 30;
            const scale = Math.max(0.2, Math.min(1.5, r.width / (maxX - minX), r.height / (maxY - minY)));
            view = {
                scale,
                x: (r.width - (maxX - minX) * scale) / 2 - minX * scale,
                y: (r.height - (maxY - minY) * scale) / 2 - minY * scale
            };
        }
        render();
    }

    // ----------------------------------------------------------------- mouse

    // mousedown decides which gesture starts; its state lives in `drag`. mousemove and mouseup listen on
    // window, so a drag continues when the pointer leaves the canvas. Positions are in diagram coordinates.
    // Gestures:
    //   pan      { sx, sy, vx, vy, moved }  empty canvas, middle button, or any press while simulating
    //   marquee  { start, p }               Shift+drag on empty canvas: rubber-band selection
    //   move     { ids, last, moved }       dragging the selected (top-level) states; content follows
    //   resize   { id, start, w0, h0 }      dragging the corner handle
    //   bend     { id, moved }              dragging a transition or its label
    //   link     { from, p }                Transition tool: from the source to the state under the mouseup
    // The right button is ignored.
    svg.addEventListener('mousedown', e => {
        if (!diagram || e.button === 2) {
            return;
        }
        svg.focus();
        const p = toDiagram(e);
        // Hit test: the nearest ancestor with data-kind tells what was pressed (a state group, the resize
        // handle, a transition group or an internal-transition line).
        const hit = e.target.closest('[data-kind]');
        const kind = hit && hit.dataset.kind;
        const id = hit && hit.dataset.id;

        // While simulating the diagram is read-only, so every press pans.
        if (sim || e.button === 1 || (!hit && mode === 'select' && !e.shiftKey)) {
            drag = { type: 'pan', sx: e.clientX, sy: e.clientY, vx: view.x, vy: view.y, moved: false };
            e.preventDefault();
            return;
        }
        if (!hit && mode === 'select' && e.shiftKey) {
            drag = { type: 'marquee', start: p, p };
            e.preventDefault();
            return;
        }
        // Placing tools create the element at the press (inside whatever is under it) and return to the
        // Select tool.
        if (mode === 'state' || mode === 'region' || mode === 'initial' || mode === 'final' || mode === 'history' || mode === 'choice') {
            createState(mode, p);
            setMode('select');
            return;
        }
        if (mode === 'transition') {
            // Finals, history pseudostates and regions cannot be sources; the resize handle counts as its
            // state.
            if ((kind === 'state' || kind === 'handle') && !['final', 'history', 'region'].includes(byId(id).kind)) {
                drag = { type: 'link', from: id, p };
            }
            e.preventDefault();
            return;
        }
        if (kind === 'handle') {
            const s = byId(id);
            drag = { type: 'resize', id, start: p, w0: s.w, h0: s.h };
        } else if (kind === 'state') {
            // Shift/Ctrl/Cmd+click toggles membership; a plain click on an unselected state selects just that
            // state.
            if (e.shiftKey || e.ctrlKey || e.metaKey) {
                toggleSelect(id);
            } else if (!isSelectedState(id)) {
                select({ type: 'state', id });
            } else if (selection.id !== id) {
                // Clicking a member of the group makes it the alignment reference without dropping the group.
                const ids = selectedStates();
                selectMany([id, ...ids.filter(x => x !== id)]);
            }
            // Even a plain click starts a move gesture; it commits only if the pointer actually moved.
            drag = { type: 'move', ids: topLevelOf(selectedStates()), last: p, moved: false };
        } else if (kind === 'transition') {
            select({ type: 'transition', id });
            drag = { type: 'bend', id, moved: false };
        }
        e.preventDefault();
    });

    window.addEventListener('mousemove', e => {
        if (!drag) {
            return;
        }
        const p = toDiagram(e);
        // Panning only updates the transform, no re-render. Movement over 3 pixels makes it a drag rather
        // than a click (a click on empty canvas clears the selection on mouseup).
        if (drag.type === 'pan') {
            view.x = drag.vx + e.clientX - drag.sx;
            view.y = drag.vy + e.clientY - drag.sy;
            drag.moved = drag.moved || Math.abs(e.clientX - drag.sx) + Math.abs(e.clientY - drag.sy) > 3;
            applyView();
            return;
        }
        if (drag.type === 'move') {
            // Moves are incremental (from the last pointer position) and unsnapped while dragging; snapping
            // happens on mouseup.
            const dx = p.x - drag.last.x;
            const dy = p.y - drag.last.y;
            drag.ids.forEach(id => moveBy(id, dx, dy));
            drag.last = p;
            drag.moved = true;
        } else if (drag.type === 'marquee') {
            drag.p = p;
        } else if (drag.type === 'resize') {
            const s = byId(drag.id);
            // Minimum size MIN_WIDTH x MIN_HEIGHT (also for regions).
            s.w = Math.max(MIN_WIDTH, Math.round(drag.w0 + p.x - drag.start.x));
            s.h = Math.max(MIN_HEIGHT, Math.round(drag.h0 + p.y - drag.start.y));
        } else if (drag.type === 'bend') {
            const t = transitionById(drag.id);
            // Self loops have a fixed shape and cannot be bent.
            if (t.source === t.target) {
                return;
            }
            // The curve midpoint (where the label sits) is offset from the chord midpoint by about bend / 2
            // (quadratic Bezier at t = 0.5), so twice the pointer's distance along the normal makes the curve
            // follow the pointer. Small bends snap back to straight.
            const { mid, n } = frame(t);
            const bend = 2 * ((p.x - mid.x) * n.x + (p.y - mid.y) * n.y);
            t.bend = Math.abs(bend) < 10 ? 0 : Math.round(bend);
            drag.moved = true;
        } else if (drag.type === 'link') {
            drag.p = p;
        }
        render();
    });

    window.addEventListener('mouseup', e => {
        if (!drag) {
            return;
        }
        const d = drag;
        drag = null;
        // mouseup finishes the gesture; edits are committed here once, so each gesture is one undo step.
        if (d.type === 'pan') {
            // A click on empty canvas without movement clears the selection.
            if (!d.moved && !sim && e.button === 0) {
                select(null);
            }
        } else if (d.type === 'move') {
            if (d.moved) {
                // Snap the moved roots (their content moves by the same delta), then nest them where they
                // were dropped.
                for (const id of d.ids) {
                    const s = byId(id);
                    moveBy(id, snapValue(s.x) - s.x, snapValue(s.y) - s.y);
                }
                d.ids.forEach(id => reparent(byId(id)));
                commit();
            }
        } else if (d.type === 'marquee') {
            // Add the states lying completely inside the marquee to the existing selection.
            const r = rectOf(d.start, d.p);
            const inside = diagram.states.filter(s => s.x >= r.x && s.y >= r.y && s.x + s.w <= r.x + r.w && s.y + s.h <= r.y + r.h).map(s => s.id);
            selectMany([...new Set([...selectedStates(), ...inside])]);
        } else if (d.type === 'resize') {
            // Snap the right and bottom edges (not the size) to the grid, then adopt states that now lie
            // inside and release children that no longer do.
            const s = byId(d.id);
            s.w = Math.max(MIN_WIDTH, snapValue(s.x + s.w) - s.x);
            s.h = Math.max(MIN_HEIGHT, snapValue(s.y + s.h) - s.y);
            renestResized(s);
            commit();
        } else if (d.type === 'bend') {
            if (d.moved) {
                commit();
            }
        } else if (d.type === 'link') {
            // The rubber-band line has pointer-events: none, so e.target is the element under the pointer.
            // Releasing anywhere other than a state cancels; either way the tool returns to Select.
            const target = e.target instanceof Element ? e.target.closest('[data-id]') : null;
            const targetKind = target && target.dataset.kind;
            if (target && (targetKind === 'state' || targetKind === 'handle')) {
                createTransition(d.from, target.dataset.id);
            }
            setMode('select');
        }
        render();
        renderPanel();
    });

    // Wheel zoom around the pointer: the diagram point under the cursor stays put. exp() makes the zoom step
    // proportional to the wheel delta; the scale is limited to 0.2 - 4. The listener is not passive so
    // preventDefault() can suppress the default wheel handling (scrolling, page zoom).
    svg.addEventListener(
        'wheel',
        e => {
            e.preventDefault();
            const r = svg.getBoundingClientRect();
            const mx = e.clientX - r.left;
            const my = e.clientY - r.top;
            const scale = Math.max(0.2, Math.min(4, view.scale * Math.exp(-e.deltaY * 0.0015)));
            view.x = mx - ((mx - view.x) * scale) / view.scale;
            view.y = my - ((my - view.y) * scale) / view.scale;
            view.scale = scale;
            applyView();
        },
        { passive: false }
    );

    // Double-click on a state selects it and focuses its Name field for renaming (pseudostates without a name
    // field are just selected).
    svg.addEventListener('dblclick', e => {
        const hit = e.target.closest('[data-kind="state"]');
        if (hit && !sim) {
            select({ type: 'state', id: hit.dataset.id });
            const input = document.getElementById('prop-name');
            if (input) {
                input.focus();
                input.select();
            }
        }
    });

    // ---------------------------------------------------------------- nudging
    // Arrow keys move the selection without a gesture that has a natural end, so a burst of nudges (a held
    // key or quick taps) is gathered into one pending edit, like a drag: the states move on every key press,
    // and NUDGE_IDLE_MS after the last press finishNudge() re-nests the moved states and commits once, so the
    // whole burst is one undo step. Any other interaction finishes a pending nudge first (see the capture
    // listeners below), so no other edit, gesture, toolbar action (save via Ctrl+S, Simulate, Layout,
    // Generate, export) or posted message can see the moved but uncommitted state. An external document
    // change arriving meanwhile wins: the update replaces the model and the pending nudge is dropped.
    // `nudge` is { ids, timer } (the moved top-level state ids and the idle timer) or null.
    const NUDGE_IDLE_MS = 400;
    let nudge = null;

    /** Moves the selected (top-level) states by dx / dy and (re)starts the idle timer of the pending nudge. */
    function nudgeBy(dx, dy) {
        const ids = topLevelOf(selectedStates());
        ids.forEach(id => moveBy(id, dx, dy));
        if (!nudge) {
            nudge = { ids: new Set(), timer: 0 };
        }
        ids.forEach(id => nudge.ids.add(id));
        clearTimeout(nudge.timer);
        nudge.timer = setTimeout(() => finishNudge(true), NUDGE_IDLE_MS);
        render();
    }

    /**
     * Ends a pending nudge: nests the moved states where they now are (reparent, the same rules as dropping
     * them after a drag) and commits. The side panel, which shows the parent, is only rebuilt when
     * `refreshPanel` is set (idle timer, leaving the webview); when another interaction ends the nudge,
     * rebuilding it could remove the very control being clicked, and that interaction redraws what it
     * changes anyway.
     */
    function finishNudge(refreshPanel) {
        if (!nudge) {
            return;
        }
        clearTimeout(nudge.timer);
        const ids = nudge.ids;
        nudge = null;
        if (!diagram) {
            return;
        }
        [...ids].map(byId).filter(Boolean).forEach(reparent);
        commit();
        render();
        if (refreshPanel) {
            renderPanel();
        }
    }

    /** Drops a pending nudge without committing it (the document was replaced from outside). */
    function cancelNudge() {
        if (nudge) {
            clearTimeout(nudge.timer);
            nudge = null;
        }
    }

    // Capture-phase listeners run before every other handler of the page, so a pending nudge is committed
    // before any press, clipboard action or key does anything else. Keys that continue the burst are
    // exempt: further arrow keys (outside form controls) and Shift (held for the large step); Ctrl / Cmd /
    // Alt do finish it, so shortcuts handled by VS Code (save, undo) see the committed text. Leaving the
    // webview (blur, hidden) finishes it as well.
    for (const type of ['mousedown', 'copy', 'cut', 'paste']) {
        document.addEventListener(type, () => finishNudge(false), true);
    }
    document.addEventListener(
        'keydown',
        e => {
            if (e.key === 'Shift' || (e.key.startsWith('Arrow') && !isEditingText(e.target))) {
                return;
            }
            finishNudge(false);
        },
        true
    );
    window.addEventListener('blur', () => finishNudge(true));
    document.addEventListener('visibilitychange', () => finishNudge(true));

    // ------------------------------------------------------------------- help
    // The ? toolbar button (or the ? key) opens a modal <dialog> with the mouse and keyboard shortcuts, the
    // transition notation and buttons that ask the host to open the user manual or the Get Started
    // walkthrough. It is built on first use. While it is open, the editor's own keyboard and clipboard
    // shortcuts are off (see helpOpen() in the listeners), so keys typed into the help cannot change the
    // diagram; Escape, the ? key, the × button and a click on the backdrop close it.
    const MOD = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent) ? 'Cmd' : 'Ctrl';
    // Sections of [title, how the left column is shown, rows]: mouse gestures as plain text, keys as keycaps
    // (<kbd>) and notation as code.
    const HELP = [
        [
            'Mouse',
            'gesture',
            [
                ['Tool, then click', 'Add a state or pseudostate; click inside a state to nest it'],
                ['Transition, then drag', 'Connect a source to a target'],
                ['Click', 'Select a state or transition'],
                ['Shift / ' + MOD + '+click', 'Add a state to or remove it from the selection'],
                ['Shift+drag', 'Select the states in a rectangle'],
                ['Drag', 'Move states; on empty canvas (or with the middle button), pan'],
                ['Drag the corner handle', 'Resize a state'],
                ['Drag a transition label', 'Curve the transition'],
                ['Double-click a state', 'Rename it'],
                ['Wheel', 'Zoom']
            ]
        ],
        [
            'Keyboard',
            'kbd',
            [
                ['Delete / Backspace', 'Delete the selection'],
                ['Esc', 'Cancel, back to the Select tool, clear the selection'],
                [MOD + '+C / X / V', 'Copy, cut, paste'],
                [MOD + '+D', 'Duplicate'],
                [MOD + '+A', 'Select all states'],
                ['Arrow keys', 'Nudge (Shift: 5 grid steps)'],
                [MOD === 'Cmd' ? 'Cmd+Z / Cmd+Shift+Z' : 'Ctrl+Z / Ctrl+Y', 'Undo, redo'],
                ['?', 'Show or hide this help']
            ]
        ],
        [
            'Notation',
            'code',
            [
                ['Event [guard] / a1; a2', 'Transition: event, optional guard, actions separated by ;'],
                ['after(500ms), after(2s), after(1min)', 'Timeout event'],
                ['(no event)', 'Completion transition, taken when the state has completed'],
                ['Internal (no exit / entry)', 'Handle an event without leaving the state'],
                ['H / H*', 'Shallow / deep history']
            ]
        ]
    ];
    let helpDialog = null;

    /** True while the help dialog is shown. */
    function helpOpen() {
        return !!(helpDialog && helpDialog.open);
    }

    /** Builds the help dialog (once) and returns it. */
    function helpElement() {
        if (helpDialog) {
            return helpDialog;
        }
        const close = () => helpDialog.close();
        const term = { gesture: 'span', kbd: 'kbd', code: 'code' };
        // The close button comes first, so showModal() focuses it rather than a button further down, which
        // would scroll a tall dialog to its end.
        const closeButton = el('button', { class: 'help-close', title: 'Close (Esc)', onclick: close }, '×');
        closeButton.setAttribute('aria-label', 'Close');
        const body = el(
            'div',
            { class: 'help-body' },
            el('div', { class: 'help-header' }, el('h2', {}, 'MachinaState help'), closeButton),
            el(
                'div',
                { class: 'help-sections' },
                ...HELP.map(([title, kind, rows]) =>
                    el(
                        'section',
                        { class: kind },
                        el('h3', {}, title),
                        el('dl', {}, ...rows.flatMap(([keys, text]) => [el('dt', {}, el(term[kind], {}, keys)), el('dd', {}, text)]))
                    )
                )
            ),
            el(
                'div',
                { class: 'help-actions' },
                el('button', { class: 'primary', onclick: () => vscode.postMessage({ type: 'openManual' }) }, 'Open User Manual'),
                el('button', { onclick: () => vscode.postMessage({ type: 'getStarted' }) }, 'Get Started')
            )
        );
        // A click on the dialog element itself (not on its content) is a click on the backdrop.
        helpDialog = el('dialog', { id: 'help', onclick: e => e.target === helpDialog && close() }, body);
        helpDialog.setAttribute('aria-labelledby', 'help-title');
        body.querySelector('h2').id = 'help-title';
        document.body.append(helpDialog);
        return helpDialog;
    }

    /** Opens the help dialog, or closes it if it is open. */
    function toggleHelp() {
        if (helpOpen()) {
            helpDialog.close();
        } else {
            finishNudge(true);
            helpElement().showModal();
        }
    }

    // Keyboard shortcuts (ignored while typing in a form control):
    // - Delete / Backspace: delete the selection.
    // - Escape: cancel a link or marquee gesture, return to the Select tool and clear the selection.
    // - Ctrl+D: duplicate (copy + paste through the internal clipboard; the system clipboard is untouched).
    // - Ctrl+A: select all top-level states (nested ones follow their parent anyway).
    // - Arrow keys: nudge by 1 unit, one grid step with Snap on, or 5 grid steps with Shift. A burst of
    //   nudges is one commit, after which the moved states are re-nested (see nudgeBy above).
    // - ?: show or hide the help dialog. While it is open no other shortcut applies (the dialog closes
    //   itself on Escape).
    // Ctrl+C / X / V are handled by the clipboard events above; Ctrl+Z / Y are VS Code's document undo /
    // redo.
    document.addEventListener('keydown', e => {
        if (isEditingText(e.target)) {
            return;
        }
        const ctrl = e.ctrlKey || e.metaKey;
        if (e.key === '?' && !ctrl && !e.altKey) {
            toggleHelp();
            e.preventDefault();
            return;
        }
        if (helpOpen()) {
            return;
        }
        if (e.key === 'Delete' || e.key === 'Backspace') {
            deleteSelection();
            e.preventDefault();
        } else if (e.key === 'Escape') {
            if (drag && (drag.type === 'link' || drag.type === 'marquee')) {
                drag = null;
            }
            setMode('select');
            select(null);
        } else if (ctrl && e.key.toLowerCase() === 'd' && !sim) {
            if (copySelection()) {
                paste(clipboard);
            }
            e.preventDefault();
        } else if (ctrl && e.key.toLowerCase() === 'a' && diagram && !sim) {
            selectMany(diagram.states.filter(s => !s.parent).map(s => s.id));
            e.preventDefault();
        } else if (e.key.startsWith('Arrow') && selectedStates().length && !sim) {
            const step = e.shiftKey ? GRID * 5 : snap ? GRID : 1;
            const dx = e.key === 'ArrowLeft' ? -step : e.key === 'ArrowRight' ? step : 0;
            const dy = e.key === 'ArrowUp' ? -step : e.key === 'ArrowDown' ? step : 0;
            nudgeBy(dx, dy);
            e.preventDefault();
        }
    });

    // --------------------------------------------------------------- toolbar

    document.querySelectorAll('#tools button[data-mode]').forEach(b => b.addEventListener('click', () => setMode(b.dataset.mode)));
    document.getElementById('btn-delete').addEventListener('click', deleteSelection);
    document.getElementById('btn-fit').addEventListener('click', fit);
    // Layout runs on the host (src/layout.ts); the result comes back as an ordinary document update.
    document.getElementById('btn-layout').addEventListener('click', () => {
        if (diagram && !sim) {
            fitted = false; // fit the view to the new layout when it arrives
            vscode.postMessage({ type: 'autoLayout' });
        }
    });
    document.getElementById('btn-png').addEventListener('click', () => {
        exportPng().catch(err => console.error('PNG export failed', err));
    });
    document.getElementById('btn-svg').addEventListener('click', exportSvg);
    // Snap is per-webview UI state persisted with vscode.setState (not stored in the document).
    const applySnap = () => {
        snapButton.classList.toggle('on', snap);
        vscode.setState({ ...(vscode.getState() || {}), snap });
    };
    snapButton.addEventListener('click', () => {
        snap = !snap;
        applySnap();
    });
    applySnap();
    simButton.addEventListener('click', toggleSim);
    document.getElementById('btn-help').addEventListener('click', toggleHelp);
    // Generate Code: the host generates code for the document with the selected language and style (it
    // validates both values).
    document.getElementById('btn-gen').addEventListener('click', () => {
        vscode.postMessage({ type: 'generate', language: langSelect.value, style: styleSelect.value });
    });
    // The code generation options are stored in the document (diagram.codegen), so changing them is an
    // undoable edit; other codegen members such as queueCapacity are kept.
    const saveCodegen = () => {
        if (!diagram) {
            return;
        }
        diagram.codegen = {
            ...diagram.codegen,
            language: langSelect.value,
            style: styleSelect.value,
            trace: traceCheck.checked,
            threadSafe: threadSafeCheck.checked,
            queue: queueCheck.checked
        };
        commit();
    };
    langSelect.addEventListener('change', saveCodegen);
    styleSelect.addEventListener('change', saveCodegen);
    traceCheck.addEventListener('change', saveCodegen);
    threadSafeCheck.addEventListener('change', saveCodegen);
    queueCheck.addEventListener('change', saveCodegen);

    // ------------------------------------------------------------- messaging

    // Messages from the extension host: 'update' carries the document text, 'validation' the analyzer's
    // problems. Anything else that reaches the window (other message types, or messages without the
    // expected payload) is ignored rather than trusted: an update needs a string text, and only problem
    // entries that are objects are kept, with the message turned into text and an id kept only if it is a
    // string.
    window.addEventListener('message', e => {
        const msg = e.data;
        if (!msg || typeof msg !== 'object') {
            return;
        }
        if (msg.type === 'update' && typeof msg.text === 'string') {
            // Line endings are normalised so a CRLF file compares equal to our LF serialization. A text equal
            // to lastText is the echo of our own commit (or nothing new) and is ignored, which keeps the
            // selection and any gesture intact.
            const text = msg.text.replace(/\r\n/g, '\n');
            if (text === lastText) {
                return;
            }
            lastText = text;
            cancelNudge();
            try {
                // An empty file is an empty diagram. Invalid JSON hides the diagram and shows the error
                // banner until the text is fixed.
                diagram = normalize(text.trim() ? JSON.parse(text) : {});
                parseErrorBox.hidden = true;
            } catch (err) {
                diagram = null;
                parseErrorBox.hidden = false;
                parseErrorBox.textContent = 'The file is not valid JSON: ' + err.message + '. Fix it in the text editor (Reopen Editor With... > Text Editor).';
            }
            if (diagram) {
                // Keep the selection while its elements still exist (e.g. after undo), restart a running
                // simulation on the new model, and sync the toolbar's code generation controls with the
                // document.
                if (selection && !(selection.type === 'state' ? byId(selection.id) : transitionById(selection.id))) {
                    selection = null;
                }
                multi = new Set([...multi].filter(byId));
                if (sim) {
                    startSim();
                }
                langSelect.value = diagram.codegen.language;
                styleSelect.value = diagram.codegen.style;
                traceCheck.checked = diagram.codegen.trace === true;
                threadSafeCheck.checked = diagram.codegen.threadSafe === true;
                queueCheck.checked = diagram.codegen.queue === true;
            }
            // Fit once after the first successful load (and after Layout, which resets `fitted`).
            if (!fitted && diagram) {
                fitted = true;
                fit();
            }
            render();
            renderPanel();
            renderIssues();
        } else if (msg.type === 'validation') {
            issues = (Array.isArray(msg.issues) ? msg.issues : [])
                .filter(i => i && typeof i === 'object')
                .map(i => {
                    const issue = { ...i, message: String(i.message ?? '') };
                    if (typeof issue.id !== 'string') {
                        delete issue.id;
                    }
                    if (issue.element !== 'state' && issue.element !== 'transition') {
                        delete issue.element;
                    }
                    if (issue.severity !== 'warning') {
                        delete issue.severity;
                    }
                    return issue;
                });
            renderIssues();
        }
    });

    // Start-up: Select tool, then tell the host we are ready so it sends the document and its problems.
    setMode('select');
    vscode.postMessage({ type: 'ready' });
})();
